//     <p><strong>Beispiel:</strong> ${biases[randomIndex].example}</p>
// `;





const biases = [
            // ENTSCHEIDUNG //78
    { name: "Action Bias (Handlungsdrang)", cat: "entscheidung", desc: "Der Drang, aktiv zu handeln, selbst wenn Abwarten die bessere Strategie wäre.", example: "Ein Fußballtorhüter springt bei einem Elfmeter fast immer in eine Ecke – obwohl statistisch gesehen das Stehenbleiben in der Mitte erfolgreicher wäre." },
    { name: "Anchoring (Ankereffekt)", cat: "entscheidung", desc: "Die erste genannte Information dient als Referenzpunkt und verzerrt alle nachfolgenden Urteile.", example: "Ein Verkäufer nennt zuerst einen überhöhten Preis – der tatsächliche Preis wirkt danach wie ein Schnäppchen, auch wenn er noch immer hoch ist." },
    { name: "Base Rate Fallacy (Basisratenfehlschluss)", cat: "entscheidung", desc: "Statistische Grundraten werden zugunsten spezifischer Einzelinformationen vernachlässigt.", example: "Ein positiver Test für eine seltene Krankheit wird als sicherer Beweis gewertet – obwohl die niedrige Grundrate bedeutet, dass viele positive Tests falsch sind." },
    { name: "Belief Bias (Glaubensverzerrung)", cat: "entscheidung", desc: "Die logische Stärke eines Arguments wird danach bewertet, ob die Schlussfolgerung plausibel klingt – nicht ob die Logik stimmt.", example: "Ein Argument mit einer falschen Prämisse, das zu einer glaubwürdigen Schlussfolgerung führt, wird als logisch akzeptiert." },
    { name: "Endowment Effect (Besitztumseffekt)", cat: "entscheidung", desc: "Dinge werden allein dadurch höher bewertet, dass man sie besitzt.", example: "Jemand verlangt für sein gebrauchtes Auto deutlich mehr als er bereit wäre, für dasselbe Auto zu zahlen." },
    { name: "Confirmation Bias (Bestätigungsfehler)", cat: "entscheidung", desc: "Informationen werden bevorzugt so gesucht und interpretiert, dass sie die eigene Meinung bestätigen.", example: "Jemand, der eine bestimmte Diät für wirksam hält, liest vor allem Berichte über Erfolge – und ignoriert wissenschaftliche Gegenstudien." },
    { name: "Decoy Effect (Lockvogel-Effekt)", cat: "entscheidung", desc: "Eine bewusst minderwertige dritte Option lässt eine der anderen Optionen attraktiver erscheinen.", example: "Ein Kino bietet Small (3 €), Medium (6,50 €) und Large (7 €) an – Medium ist der Lockvogel, der Large wie ein Schnäppchen wirken lässt." },
    { name: "Disposition Effect (Dispositionseffekt)", cat: "entscheidung", desc: "Anleger verkaufen Gewinner-Aktien zu früh und halten Verlierer-Aktien zu lange.", example: "Eine Aktie im Plus wird schnell verkauft, um den Gewinn zu sichern – eine Aktie im Minus wird gehalten, in der Hoffnung, die Verluste wieder aufzuholen." },
    { name: "Escalation of Commitment (Verpflichtungssteigerung)", cat: "entscheidung", desc: "An einer Entscheidung wird trotz negativer Ergebnisse festgehalten, weil bereits Ressourcen investiert wurden.", example: "Ein Unternehmen investiert weiter Millionen in ein gescheitertes Produkt, statt das Projekt abzubrechen." },
    { name: "Framing Effect (Rahmungseffekt)", cat: "entscheidung", desc: "Dieselbe Information löst unterschiedliche Reaktionen aus, je nachdem wie sie präsentiert wird.", example: "'90 % Überlebensrate' klingt attraktiver als '10 % Sterberate' – obwohl beide Aussagen identisch sind." },
    { name: "Hyperbolic Discounting (Hyperbolische Diskontierung)", cat: "entscheidung", desc: "Sofortige Belohnungen werden gegenüber späteren, größeren Belohnungen unverhältnismäßig stark bevorzugt.", example: "Jemand gibt heute lieber 20 € aus, obwohl er weiß, dass regelmäßiges Sparen langfristig deutlich mehr bringen würde." },
    { name: "IKEA Effect (IKEA-Effekt)", cat: "entscheidung", desc: "Selbst erstellte oder zusammengebaute Dinge werden überproportional hoch bewertet.", example: "Selbst zusammengebaute Möbel werden als wertvoller empfunden als identische, bereits montierte Möbel." },
    { name: "Illusion of Control (Kontrollillusion)", cat: "entscheidung", desc: "Man glaubt, zufällige Ereignisse durch eigenes Verhalten beeinflussen zu können.", example: "Spieler entwickeln Rituale beim Würfeln, weil sie glauben, damit das Ergebnis beeinflussen zu können." },
    { name: "Information Bias (Informationsverzerrung)", cat: "entscheidung", desc: "Es werden mehr Informationen gesucht, auch wenn diese die Entscheidung nicht verbessern.", example: "Ein Arzt ordnet unnötig viele Tests an, obwohl die Zusatzdiagnostik die Behandlung nicht verändern wird." },
    { name: "Omission Bias (Unterlassungsverzerrung)", cat: "entscheidung", desc: "Unterlassungen werden als weniger schädlich bewertet als aktives Handeln mit gleichem Ergebnis.", example: "Eltern lehnen eine Impfung ab, weil sie seltene Nebenwirkungen fürchten – obwohl das Risiko durch die Krankheit selbst höher ist." },
    { name: "Optimism Bias (Optimismusverzerrung)", cat: "entscheidung", desc: "Man schätzt die eigene Wahrscheinlichkeit, von negativen Ereignissen betroffen zu sein, systematisch zu niedrig ein.", example: "Ein Gründer unterschätzt die Wahrscheinlichkeit des Scheiterns und plant Umsatz und Zeitpläne zu optimistisch." },
    { name: "Ostrich Effect (Vogel-Strauß-Effekt)", cat: "entscheidung", desc: "Negative Informationen werden aktiv vermieden, um unangenehme Erkenntnisse nicht wahrnehmen zu müssen.", example: "Anleger schauen während eines Börsencrashs bewusst nicht in ihr Depot, um sich vor schlechten Nachrichten zu schützen." },
    { name: "Outcome Bias (Ergebnisverzerrung)", cat: "entscheidung", desc: "Die Qualität einer Entscheidung wird am Ergebnis gemessen, nicht daran, ob sie zum Zeitpunkt der Wahl rational war.", example: "Ein Manager wird für eine wohlüberlegte Entscheidung kritisiert, die schlecht ausging – obwohl die Entscheidung rational korrekt war." },
    { name: "Overconfidence Bias (Überschätzungsverzerrung)", cat: "entscheidung", desc: "Eigene Fähigkeiten und die Präzision des eigenen Wissens werden systematisch überschätzt.", example: "Ein Projektmanager prognostiziert mit hoher Sicherheit den Abschluss eines Projekts – obwohl ähnliche Projekte regelmäßig länger dauern." },
    { name: "Planning Fallacy (Planungsfehlschluss)", cat: "entscheidung", desc: "Zeit und Ressourcen für eine Aufgabe werden systematisch unterschätzt.", example: "Ein Team schätzt zwei Wochen für ein Feature – obwohl ähnliche Features regelmäßig einen Monat benötigten." },
    { name: "Present Bias (Gegenwartsverzerrung)", cat: "entscheidung", desc: "Der Gegenwart wird unverhältnismäßig viel Gewicht gegeben, während die Zukunft stark abgewertet wird.", example: "Jemand gibt heute lieber Geld aus, statt für die Rente zu sparen – obwohl er die langfristigen Vorteile kennt." },
    { name: "Prospect Theory (Prospekttheorie)", cat: "entscheidung", desc: "Menschen bewerten Verluste stärker als gleichgroße Gewinne, was zu irrationalem Risikoverhalten führt.", example: "Der Verlust von 100 € schmerzt mehr als der Gewinn von 100 € Freude bereitet – obwohl der Betrag identisch ist." },
    { name: "Risk Aversion (Risikoaversion)", cat: "entscheidung", desc: "Sichere Gewinne werden gegenüber riskanten Optionen mit gleichem oder höherem Erwartungswert bevorzugt.", example: "Ein Anleger wählt 3 % sicheren Zins statt eine 50/50-Chance auf 0 % oder 7 %, obwohl letztere einen höheren Erwartungswert hat." },
    { name: "Sunk Cost Fallacy (Versunkene-Kosten-Fehlschluss)", cat: "entscheidung", desc: "An einer Entscheidung wird festgehalten, weil bereits Ressourcen investiert wurden – statt zukünftige Kosten und Nutzen neu zu bewerten.", example: "Jemand bleibt in einem schlechten Film, weil er die Kinokarte bereits bezahlt hat – obwohl er seine Zeit lieber anders nutzen würde." },
    { name: "Unit Bias (Einheiten-Verzerrung)", cat: "entscheidung", desc: "Eine vorgegebene Einheit – eine Portion, ein Paket, ein Stück – wird als Norm akzeptiert und vollständig konsumiert.", example: "Bei einer großen Packung Chips wird mehr gegessen als bei einer kleinen – nicht wegen Hunger, sondern weil die Packung als Einheit gilt." },
    { name: "Loss Aversion (Verlustaversion)", cat: "entscheidung", desc: "Verluste werden psychologisch doppelt so stark gewichtet wie gleichgroße Gewinne.", example: "Anleger halten Verlierer-Aktien zu lange, um einen realisierten Verlust zu vermeiden – und verkaufen Gewinner zu früh." },
    { name: "Status Quo Bias (Status-quo-Verzerrung)", cat: "entscheidung", desc: "Der aktuelle Zustand wird gegenüber Veränderungen bevorzugt, auch wenn eine Änderung objektiv vorteilhafter wäre.", example: "Mitarbeitende behalten ein veraltetes Software-Tool, obwohl ein effizienteres System verfügbar ist." },
    { name: "Zero-Risk Bias (Null-Risiko-Verzerrung)", cat: "entscheidung", desc: "Die vollständige Eliminierung eines Risikos wird bevorzugt, auch wenn andere Maßnahmen insgesamt mehr Schaden verhindern würden.", example: "Ein Park wird gesperrt, um das seltene Risiko eines Bienenstichs auf null zu senken – obwohl andere Maßnahmen weit mehr Verletzungen insgesamt verhindern würden." },
    { name: "Ambiguity Effect (Ambiguitätseffekt)", cat: "entscheidung", desc: "Optionen mit unbekannten Wahrscheinlichkeiten werden gegenüber solchen mit bekannten Risiken gemieden.", example: "Ein Investor wählt eine bekannte Anlage mit mäßiger Rendite statt einer vielversprechenderen, aber weniger transparenten Option – allein wegen der Ungewissheit." },
    { name: "Affect Heuristic in Decision Making (Affektbasierte Entscheidungsverzerrung)", cat: "entscheidung", desc: "Emotionale Reaktionen auf eine Option beeinflussen die Risikowahrnehmung und Entscheidung stärker als rationale Abwägung.", example: "Jemand lehnt eine medizinisch sinnvolle Operation ab, weil allein der Gedanke daran Angst auslöst – nicht wegen der tatsächlichen Risiken." },
    { name: "Blind Spot Bias in Decisions (Entscheidungs-Blinder-Fleck)", cat: "entscheidung", desc: "Man erkennt kognitive Verzerrungen bei anderen leichter als bei sich selbst, was zu unkritischen Eigenentscheidungen führt.", example: "Ein Manager kritisiert einen Kollegen für voreingenommene Personalentscheidungen – trifft selbst aber dieselben Fehler, ohne es zu merken." },
    { name: "Choice Overload (Entscheidungslähmung)", cat: "entscheidung", desc: "Zu viele Optionen führen zu schlechteren Entscheidungen oder vollständiger Entscheidungsvermeidung.", example: "Ein Supermarkt bietet 24 Marmeladensorten an – Kunden kaufen seltener als bei einem Angebot von nur 6 Sorten." },
    { name: "Clustering Illusion (Klumpenillusion)", cat: "entscheidung", desc: "Zufällige Muster werden als bedeutungsvolle Häufungen wahrgenommen und beeinflussen Entscheidungen.", example: "Ein Trader glaubt, einen wiederkehrenden Kursmuster entdeckt zu haben – tatsächlich handelt es sich um zufällige Schwankungen." },
    { name: "Commitment Bias (Verpflichtungsverzerrung)", cat: "entscheidung", desc: "Öffentlich geäußerte Positionen werden verteidigt, auch wenn neue Informationen dagegensprechen.", example: "Ein Politiker hält an einer gescheiterten Politik fest, weil er sie öffentlich angekündigt hat – ein Kurswechsel würde als Schwäche wahrgenommen." },
    { name: "Denomination Effect (Stückelungseffekt)", cat: "entscheidung", desc: "Große Geldscheine werden seltener ausgegeben als der gleichwertige Betrag in kleinen Scheinen.", example: "Jemand gibt einen 50-€-Schein ungern aus, gibt aber bereitwillig fünf 10-€-Scheine für denselben Kauf." },
    { name: "Focusing Effect (Fokussierungsverzerrung)", cat: "entscheidung", desc: "Einem einzelnen Aspekt einer Entscheidung wird zu viel Gewicht beigemessen, während andere relevante Faktoren vernachlässigt werden.", example: "Jemand zieht in eine sonnigere Stadt, überschätzt dabei den Einfluss des Wetters auf sein Glück – und unterschätzt Faktoren wie soziales Umfeld oder Arbeit." },
    { name: "Hot-Hand Fallacy (Heiße-Hand-Fehlschluss)", cat: "entscheidung", desc: "Nach einer Serie von Erfolgen wird fälschlicherweise angenommen, dass weitere Erfolge wahrscheinlicher sind.", example: "Ein Basketballfan ist überzeugt, dass ein Spieler nach fünf Treffern in Folge den nächsten Wurf sicher trifft – obwohl jeder Wurf statistisch unabhängig ist." },
    { name: "Mental Accounting (Mentale Buchführung)", cat: "entscheidung", desc: "Geld wird je nach Herkunft oder Verwendungszweck unterschiedlich bewertet, obwohl es objektiv gleich viel wert ist.", example: "Jemand gibt einen unerwarteten Bonus leichtsinnig aus, würde denselben Betrag vom Gehalt aber sorgfältig sparen." },
    { name: "Naive Diversification (Naive Diversifikation)", cat: "entscheidung", desc: "Bei mehreren Optionen wird gleichmäßig auf alle verteilt, statt rational zu gewichten.", example: "Wer drei Rentenfonds zur Auswahl hat, legt je ein Drittel in jeden – unabhängig von Rendite, Risiko oder Überschneidungen." },
    { name: "Normalcy Bias (Normalitätsverzerrung)", cat: "entscheidung", desc: "In Krisensituationen wird die Gefahr unterschätzt, weil man davon ausgeht, dass alles so bleibt wie gewohnt.", example: "Bewohner einer Überschwemmungszone evakuieren trotz Warnung nicht, weil 'so etwas hier noch nie passiert ist'." },
    { name: "Reactance (Reaktanz)", cat: "entscheidung", desc: "Wenn die eigene Entscheidungsfreiheit eingeschränkt wird, entsteht der Drang, genau die verbotene Option zu wählen.", example: "Ein Jugendlicher will einen Film unbedingt sehen, nachdem seine Eltern ihn verboten haben – obwohl er vorher kein Interesse hatte." },
    { name: "Restraint Bias (Selbstkontrollüberschätzung)", cat: "entscheidung", desc: "Die eigene Fähigkeit, Versuchungen zu widerstehen, wird überschätzt.", example: "Jemand kauft eine große Packung Süßigkeiten, weil er überzeugt ist, nur wenig davon zu essen – und isst sie in einem Sitz leer." },
    { name: "Scope Insensitivity (Umfangsunempfindlichkeit)", cat: "entscheidung", desc: "Die Bereitschaft zu helfen oder zu zahlen steigt kaum mit der Größe eines Problems.", example: "Menschen spenden ähnlich viel für die Rettung von 2.000 Vögeln wie für 200.000 – die Größenordnung beeinflusst die emotionale Reaktion kaum." },
    { name: "Decision fatigue (Entscheidungsmüdigkeit)", cat: "entscheidung", desc: "Die Qualität von Entscheidungen verschlechtert sich nach vielen Entscheidungen, weil die mentale Energie erschöpft ist.", example: "Ein Richter fällt am Ende des Tages eher zu Gunsten des Angeklagten aus, weil er müde ist und keine Energie mehr für komplexe Urteile hat." },
    { name: "Conservatism Bias (Konservatismus-Verzerrung)", cat: "entscheidung", desc: "Nach dem Erhalt neuer, eindeutiger Beweise werden die eigenen Überzeugungen nur unzureichend angepasst.", example: "Ein Analyst erhält klare neue Marktdaten, korrigiert seine ursprüngliche Prognose aber nur minimal, statt sie grundlegend zu überarbeiten." },
    { name: "Opportunity Cost Neglect (Vernachlässigung von Opportunitätskosten)", cat: "entscheidung", desc: "Bei einer Entscheidung werden die Kosten entgangener Alternativen systematisch übersehen.", example: "Jemand kauft ein teures Auto bar, ohne zu bedenken, was das investierte Geld stattdessen an Zinsen hätte einbringen können." },
    { name: "Overprecision (Übergenauigkeit)", cat: "entscheidung", desc: "Das eigene Wissen wird mit übertriebener Sicherheit als präzise und zuverlässig eingeschätzt.", example: "Ein Analyst gibt eine Umsatzprognose mit einem sehr engen Schwankungsbereich an – die tatsächlichen Werte liegen regelmäßig deutlich außerhalb dieses Bereichs." },
    { name: "Hard-Easy Effect (Leicht-Schwer-Effekt)", cat: "entscheidung", desc: "Bei schwierigen Aufgaben neigen Menschen zu Selbstüberschätzung, bei leichten Aufgaben dagegen zu Selbstunterschätzung.", example: "Vor einer kniffligen Prüfungsfrage überschätzt jemand seine Erfolgschancen deutlich – bei einer trivialen Frage unterschätzt er sie dagegen." },
    { name: "Illusory Superiority (Illusorische Überlegenheit)", cat: "entscheidung", desc: "Die eigenen Fähigkeiten werden systematisch als überdurchschnittlich eingeschätzt, unabhängig von der tatsächlichen Leistung.", example: "Die meisten Autofahrer halten sich für überdurchschnittlich gute Fahrer – statistisch kann das nicht für die Mehrheit zutreffen." },
    { name: "Worse-Than-Average Effect (Schlechter-als-der-Durchschnitt-Effekt)", cat: "entscheidung", desc: "Bei als schwierig empfundenen Aufgaben unterschätzen Menschen systematisch die eigenen Fähigkeiten im Vergleich zu anderen.", example: "Vor einer komplexen Programmieraufgabe glauben viele, schlechter abzuschneiden als der Durchschnitt ihrer Kollegen – obwohl objektiv kein Unterschied besteht." },
    { name: "Ballot Order Effect (Wahlzettel-Reihenfolgeeffekt)", cat: "entscheidung", desc: "Die Position einer Option oder eines Namens auf einem Stimmzettel beeinflusst die Wahlentscheidung, unabhängig von inhaltlichen Qualifikationen.", example: "Kandidaten, die zuerst auf dem Stimmzettel gelistet sind, erhalten bei sonst gleicher Qualifikation systematisch mehr Stimmen als später gelistete." },
    { name: "Money Illusion (Geldillusion)", cat: "entscheidung", desc: "Geldbeträge werden nach ihrem nominalen statt ihrem tatsächlichen, inflationsbereinigten Wert bewertet.", example: "Eine Gehaltserhöhung von 3 % bei 5 % Inflation fühlt sich positiv an – obwohl real weniger Kaufkraft übrig bleibt als vorher." },
    { name: "Magical Thinking (Magisches Denken)", cat: "entscheidung", desc: "Ursache-Wirkungs-Zusammenhänge werden zwischen Ereignissen angenommen, die tatsächlich in keinem kausalen Zusammenhang stehen.", example: "Ein Sportler trägt vor jedem wichtigen Spiel dieselben Socken, überzeugt, dass sie zum Sieg beitragen." },
    { name: "Empathy Gap (Empathielücke)", cat: "entscheidung", desc: "Entscheidungen werden im aktuellen emotionalen Zustand getroffen, ohne zu bedenken, wie anders man in einem anderen Zustand entscheiden würde.", example: "Im gut gesättigten Zustand plant jemand einen bescheidenen Wocheneinkauf – im hungrigen Zustand im Supermarkt landen dann deutlich mehr Süßigkeiten im Wagen, als vorher beabsichtigt war." },
    { name: "Impact Bias (Wirkungsverzerrung)", cat: "entscheidung", desc: "Die emotionale Intensität und Dauer zukünftiger Ereignisse wird systematisch überschätzt.", example: "Jemand glaubt, eine Beförderung werde ihn monatelang glücklich machen – tatsächlich verfliegt die gesteigerte Zufriedenheit meist schon nach wenigen Wochen." },
    { name: "Projection Bias (Projektionsverzerrung)", cat: "entscheidung", desc: "Man geht davon aus, dass zukünftige Vorlieben und Bedürfnisse den heutigen entsprechen werden.", example: "Ein Berufsanfänger geht davon aus, dass ihm derselbe Beruf auch in 20 Jahren noch genauso viel Freude bereiten wird wie heute – ohne zu bedenken, dass sich Vorlieben im Laufe des Lebens verändern." },
    { name: "Pessimism Bias (Pessimismusverzerrung)", cat: "entscheidung", desc: "Man schätzt die eigene Wahrscheinlichkeit, von positiven Ereignissen zu profitieren, systematisch zu niedrig ein.", example: "Jemand rechnet vor einem Bewerbungsgespräch fest mit einer Absage – selbst bei starker Qualifikation für die Stelle." },
    { name: "Illusion of Validity (Validitätsillusion)", cat: "entscheidung", desc: "Ein Urteil wird als sicher empfunden, weil die zugrunde liegenden Informationen ein stimmiges Muster ergeben – nicht, weil es tatsächlich zuverlässig ist.", example: "Ein Personaler ist nach einem einzigen überzeugenden Vorstellungsgespräch völlig sicher in seiner Einschätzung eines Kandidaten – obwohl solche Eindrücke den späteren Berufserfolg kaum vorhersagen." },
    { name: "Semmelweis Reflex (Semmelweis-Reflex)", cat: "entscheidung", desc: "Neue Erkenntnisse werden reflexartig abgelehnt, allein weil sie etablierten Normen oder Paradigmen widersprechen.", example: "Eine neue, gut belegte Arbeitsmethode wird von erfahrenen Fachleuten zunächst abgelehnt – einfach weil sie der bisherigen Praxis widerspricht." },
    { name: "Time-Saving Bias (Zeitersparnis-Verzerrung)", cat: "entscheidung", desc: "Die Zeitersparnis durch höhere Geschwindigkeit wird bei bereits hohem Tempo überschätzt und bei niedrigem Tempo unterschätzt.", example: "Ein Fahrer erhöht sein Tempo von 130 auf 150 km/h in der Annahme, deutlich Zeit zu sparen – auf einer langen Strecke beträgt der Unterschied tatsächlich nur wenige Minuten." },
    { name: "Distinction Bias (Unterscheidungsverzerrung)", cat: "entscheidung", desc: "Beim direkten Vergleich zweier Optionen werden Unterschiede stärker gewichtet als bei getrennter Beurteilung.", example: "Zwei Fernseher wirken im direkten Vergleich im Laden sehr unterschiedlich – zu Hause, wo nur einer steht, fällt der Unterschied kaum auf." },
    { name: "Congruence Bias (Kongruenzverzerrung)", cat: "entscheidung", desc: "Hypothesen werden ausschließlich durch direkte Tests geprüft, statt alternative Erklärungen zu berücksichtigen.", example: "Ein Entwickler testet seinen Code nur mit Eingaben, von denen er erwartet, dass sie funktionieren – und übersieht dabei systematisch Randfälle." },
    { name: "Observer-Expectancy Effect (Beobachtererwartungseffekt)", cat: "entscheidung", desc: "Die Erwartungen eines Beobachters beeinflussen unbewusst das Ergebnis eines Experiments oder einer Untersuchung.", example: "Ein Forscher, der an die Wirksamkeit eines Medikaments glaubt, interpretiert mehrdeutige Patientendaten unbewusst als positiv." },
    { name: "Observer-Expectancy Effect (Beobachtererwartungseffekt)", cat: "entscheidung", desc: "Die Erwartungen eines Beobachters beeinflussen unbewusst die Interpretation von Ergebnissen in die erwartete Richtung.", example: "Ein Forscher, der erwartet, dass ein Medikament stark wirkt, ordnet eine mehrdeutige Patientenreaktion eher als 'Verbesserung' ein – statt als 'keine Veränderung'." },
    { name: "Blind Spot Bias in Decisions (Entscheidungs-Blinder-Fleck)", cat: "entscheidung", desc: "Weil man den eigenen Bias nicht erkennt, fließt er unkontrolliert in Entscheidungen ein und verzerrt sie systematisch.", example: "Ein Manager hält sich für besonders neutral – und bevorzugt trotzdem unbewusst die eigene Abteilung bei Ressourcenentscheidungen, weil er seinen blinden Fleck nicht einkalkuliert." },
    { name: "Murphy's Law (Murphys Gesetz)", cat: "entscheidung", desc: "Die Erwartung, dass alles, was schiefgehen kann, auch schiefgehen wird, beeinflusst Risikowahrnehmung und Entscheidungen.", example: "Ein Projektmanager plant übermäßig viele Puffer ein, weil er fest davon überzeugt ist, dass garantiert etwas schieflaufen wird." },
    { name: "Zero-Sum Thinking (Nullsummen-Denken)", cat: "entscheidung", desc: "Eine Situation wird fälschlicherweise als Nullsummenspiel wahrgenommen, obwohl alle Beteiligten gewinnen könnten.", example: "In Verhandlungen glaubt jemand, jedes Zugeständnis an die Gegenseite sei automatisch ein Verlust für sich selbst – obwohl eine Einigung für beide vorteilhaft wäre." },
    { name: "Risk Compensation (Risikoausgleich)", cat: "entscheidung", desc: "Menschen gehen mehr Risiken ein, wenn sie sich durch Schutzmaßnahmen sicherer fühlen.", example: "Autofahrer fahren schneller und unvorsichtiger, wenn sie Sicherheitsgurt und Airbag haben – weil das subjektive Sicherheitsgefühl steigt." },
    { name: "Subadditivity Effect (Subadditivitätseffekt)", cat: "entscheidung", desc: "Die Wahrscheinlichkeit eines Gesamtereignisses wird als geringer eingeschätzt als die Summe seiner Teilwahrscheinlichkeiten.", example: "Jemand schätzt die Wahrscheinlichkeit 'Tod durch irgendeine Krankheit' geringer ein als die Summe der Einzelwahrscheinlichkeiten aller Krankheiten zusammen." },
    { name: "Self-Consistency Bias (Selbstkonsistenz-Verzerrung)", cat: "entscheidung", desc: "Menschen überschätzen, wie konsistent ihr vergangenes Verhalten und ihre früheren Überzeugungen mit ihrem heutigen Selbstbild waren.", example: "Jemand erinnert sich, schon immer umweltbewusst gewesen zu sein – obwohl er früher kaum auf Nachhaltigkeit geachtet hat." },
    { name: "Pro-Innovation Bias (Pro-Innovations-Verzerrung)", cat: "entscheidung", desc: "Neue Innovationen werden unkritisch positiv bewertet, während ihre Nachteile oder Risiken systematisch unterschätzt werden.", example: "Ein Unternehmen führt eine neue Software ein, weil sie modern und innovativ wirkt – ohne die tatsächlichen Kosten, Lernkurven oder Risiken zu prüfen." },
    { name: "Declinism (Verfallsdenken)", cat: "entscheidung", desc: "Die Vergangenheit wird idealisiert und die Gegenwart oder Zukunft als schlechter wahrgenommen, als sie tatsächlich ist.", example: "'Früher war alles besser' – obwohl objektive Daten zeigen, dass Lebensqualität, Gesundheit und Wohlstand gestiegen sind." },
    { name: "Illusion of External Agency (Illusion externer Kontrolle)", cat: "entscheidung", desc: "Eigene unbewusste Gedanken oder Handlungen werden faälschlierweise als von außen gesteuert wahrgenommen, was die Verantwortung für Entscheidungen verzerrt.",  example: "Beim Gläserrücken sind Teilnehmer überzeugt, eine Geisterkraft bewege das Glas - tatsächlich bewegen sie es unbewusst selbst." },
    { name: "Effort Justification (Anstrengungsrechtfertigung)", cat: "entscheidung", desc: "Je mehr Mühe oder Leid in etwas investiert wurde, desto höher wird der Wert dieser Sache im Nachhinein eingeschätzt.", example: "Wer eine besonders anstrengende Aufnahmeprüfung für einen Verein bestanden hat, schätzt die Mitgliedschaft danach wertvoller ein als jemand, der leicht aufgenommen wurde." },
    { name: "Pseudocertainty Effect (Pseudosicherheitseffekt)", cat: "entscheidung", desc: "Ergebnisse, die in mehreren Schritten präsentiert werden, wirken sicherer als objektiv gleichwertige Wahrscheinlichkeiten, die direkt genannt werden.", example: "Eine Versicherung, die 'garantierten' Schutz vor einem Teilrisiko bewirbt und ein zweites Risiko separat nennt, wirkt attraktiver als dieselbe Police mit einer einzigen Gesamtwahrscheinlichkeit." },
    { name: "Law of Triviality (Trivialitätsgesetz)", cat: "entscheidung", desc: "Gruppen verbringen unverhältnismäßig viel Zeit mit trivialen Themen, während komplexe, wichtige Entscheidungen kaum diskutiert werden.", example: "In einem Meeting wird 30 Minuten über die Farbe des neuen Firmenlogos diskutiert, während das Millionenbudget in 5 Minuten ohne echte Debatte abgenickt wird." },
    { name: "Less-Is-Better Effect (Weniger-ist-besser-Effekt)", cat: "entscheidung", desc: "Bei getrennter Bewertung wird eine Option mit objektiv weniger oder geringerwertigen Eigenschaften manchmal höher geschätzt als eine bessere Option.", example: "Ein kleines, aber elegant verpacktes Geschenk wirkt bei getrennter Betrachtung großzügiger als ein größeres, schlichter verpacktes Geschenk gleichen Werts." },
    { name: "Peltzman Effect (Peltzman-Effekt)", cat: "entscheidung", desc: "Sicherheitsmaßnahmen oder Regulierungen werden teilweise wirkungslos, weil sich Menschen dadurch sicherer fühlen und riskanter handeln.", example: "Ein Auto mit besseren Bremsen und mehr Sicherheitsausstattung verleitet den Fahrer dazu, schneller zu fahren oder weniger Abstand zu halten – ein Teil des Sicherheitsgewinns wird dadurch wieder aufgezehrt." },


            // SOZIAL //54
    { name: "Actor-Observer Bias (Akteur-Beobachter-Bias)", cat: "sozial", desc: "Eigenes Verhalten wird auf äußere Umstände zurückgeführt, das Verhalten anderer auf deren Charakter.", example: "Du kommst zu spät, weil der Bus Verspätung hatte – ein Freund kommt zu spät und du denkst: 'Der ist halt unpünktlich.'" },
    { name: "Affinity Bias (Ähnlichkeitseffekt)", cat: "sozial", desc: "Menschen bevorzugen unbewusst andere, die ihnen selbst ähnlich sind.", example: "Ein Bewerber mit gleichem Studiengang oder ähnlichen Hobbys wird bevorzugt, obwohl die Qualifikationen vergleichbar sind." },
    { name: "Authority Bias (Autoritätsfehler)", cat: "sozial", desc: "Der Meinung einer Autoritätsperson wird gefolgt, auch wenn eigene Fakten dagegensprechen.", example: "Eine Führungskraft nennt einen Vorschlag falsch – du stimmst zu, obwohl du Belege für das Gegenteil hast." },
    { name: "Barnum Effect / Forer Effect (Barnum-Effekt / Forer-Effekt)", cat: "sozial", desc: "Vage, allgemein gehaltene Aussagen werden als präzise persönliche Beschreibung wahrgenommen.", example: "Ein Horoskop fühlt sich für viele Leser sehr zutreffend an, obwohl es auf fast jeden zutreffen könnte." },
    { name: "Benjamin Franklin Effect (Benjamin-Franklin-Effekt)", cat: "sozial", desc: "Wer jemandem einen Gefallen tut, mag diese Person danach mehr – nicht umgekehrt.", example: "Du hilfst einem unsympathischen Kollegen bei einer Aufgabe und findest ihn danach deutlich sympathischer." },
    { name: "Correspondence Bias (Korrespondenz-Verzerrung)", cat: "sozial", desc: "Die allgemeine Tendenz, Verhalten auf Persönlichkeit zurückzuführen und situative Faktoren zu vernachlässigen.", example: "Jemand ist unhöflich – man schlussfolgert sofort, dass die Person generell unfreundlich ist, ohne einen schlechten Tag als Ursache in Betracht zu ziehen." },    
    { name: "Cross-Race Effect (Andere-Ethnien-Effekt)", cat: "sozial", desc: "Gesichter der eigenen ethnischen Gruppe werden zuverlässiger erkannt als Gesichter anderer Gruppen.", example: "Wer hauptsächlich Gesichter aus der eigenen ethnischen Gruppe kennt, unterscheidet Personen anderer Gruppen schlechter." },
    { name: "Dunning-Kruger Effect (Dunning-Kruger-Effekt)", cat: "sozial", desc: "Wenig kompetente Menschen überschätzen ihre Fähigkeiten, weil ihnen das Wissen fehlt, eigene Fehler zu erkennen.", example: "Jemand mit wenig Programmiererfahrung glaubt, alles zu verstehen – erfahrene Entwickler sehen die grundlegenden Fehler sofort." },
    { name: "Egocentric Bias (Egozentrismus-Verzerrung)", cat: "sozial", desc: "Die eigene Perspektive wird unbewusst als universelle Sichtweise angenommen.", example: "Jemand geht davon aus, dass alle anderen denselben Film langweilig finden, weil er selbst gelangweilt war." },
    { name: "False Consensus Effect (Falscher-Konsens-Effekt)", cat: "sozial", desc: "Die eigene Meinung oder das eigene Verhalten wird für weiter verbreitet gehalten, als es tatsächlich ist.", example: "Jemand, der gerne spät isst, glaubt, die meisten Menschen täten das auch." },
    { name: "Fundamental Attribution Error (Fundamentaler Attributionsfehler)", cat: "sozial", desc: "Eine spezifische Ausprägung des Correspondence Bias: Beobachter überbewerten bei der Beurteilung sozialer Situationen den Charakter und ignorieren situative Umstände.", example: "Bei einer Quizshow wirkt der Quizmaster besonders intelligent – dabei liegt es vor allem an der Situation: Er kennt die Antworten, weil er die Fragen selbst ausgewählt hat." },    
    { name: "Halo Effect (Halo-Effekt)", cat: "sozial", desc: "Ein einzelnes positives Merkmal einer Person überstrahlt die Wahrnehmung aller anderen Eigenschaften.", example: "Eine attraktive Person wird automatisch auch als kompetenter und vertrauenswürdiger eingeschätzt." },
    { name: "Ingroup Bias (Eigengruppen-Bevorzugung)", cat: "sozial", desc: "Mitglieder der eigenen Gruppe werden gegenüber Außenstehenden bevorzugt behandelt und bewertet.", example: "In einer Projektgruppe werden Ideen von Teammitgliedern wohlwollender aufgenommen als gleiche Ideen von Außenstehenden." },
    { name: "Ingroup Favoritism (Eigengruppen-Bevorzugung)", cat: "sozial", desc: "Eine konkrete Ausprägung des Ingroup Bias: Mitglieder der eigenen Gruppe werden bei Entscheidungen aktiv bevorzugt behandelt.", example: "Bewerber aus der eigenen sozialen oder beruflichen Gruppe erhalten häufiger Gesprächseinladungen und bessere Bewertungen – bei objektiv gleicher Qualifikation." },
    { name: "Interviewer Bias (Interviewer-Verzerrung)", cat: "sozial", desc: "Erwartungen des Interviewers beeinflussen unbewusst den Verlauf und die Auswertung eines Gesprächs.", example: "Ein Interviewer, der einen Kandidaten vorab als 'vielversprechend' eingestuft hat, stellt unbewusst wohlwollendere Folgefragen." },
    { name: "Bandwagon Effect (Mitläufereffekt)", cat: "sozial", desc: "Meinungen oder Verhaltensweisen werden übernommen, weil viele andere es ebenfalls tun.", example: "Eine Aktie wird gekauft, weil alle darüber reden – nicht wegen eigener Analyse." },
    { name: "Pygmalion Effect (Pygmalion-Effekt)", cat: "sozial", desc: "Hohe Erwartungen an eine Person können deren tatsächliche Leistung messbar steigern.", example: "Schüler, von denen Lehrer viel erwarten, schneiden im Laufe des Jahres tatsächlich besser ab." },
    { name: "Self-Serving Bias (Selbstwertdienliche Verzerrung)", cat: "sozial", desc: "Erfolge werden den eigenen Fähigkeiten zugeschrieben, Misserfolge äußeren Umständen.", example: "Eine gute Note kommt von harter Arbeit – eine schlechte Note lag an der unfairen Prüfung." },
    { name: "Social Desirability Bias (Soziale Erwünschtheit)", cat: "sozial", desc: "Antworten werden so gewählt, dass sie gesellschaftlichen Normen entsprechen statt der Wahrheit.", example: "In einer Umfrage zur Ernährung geben viele an, mehr Gemüse zu essen als tatsächlich der Fall ist." },
    { name: "Spotlight Effect (Spotlight-Effekt)", cat: "sozial", desc: "Man überschätzt, wie stark andere das eigene Aussehen oder Verhalten wahrnehmen und bewerten.", example: "Wer einen Fleck auf dem Shirt hat, glaubt, alle würden ihn bemerken – die meisten anderen achten gar nicht darauf." },
    { name: "Stereotype (Stereotyp)", cat: "sozial", desc: "Verallgemeinernde Annahmen über Gruppen werden auf einzelne Mitglieder dieser Gruppe übertragen.", example: "Weil jemand aus einem bestimmten Land kommt, wird angenommen, er sei pünktlich oder temperamentvoll." },
    { name: "Unconscious Bias (Unbewusste Vorurteile)", cat: "sozial", desc: "Unbewusste Vorannahmen beeinflussen Urteile und Entscheidungen, ohne dass man es merkt.", example: "Ein Personalentscheider wählt unbewusst häufiger Bewerber mit einem Namen aus, der der eigenen Kultur vertraut klingt." },
    { name: "Ultimate Attribution Error (Ultimativer Attributionsfehler)", cat: "sozial", desc: "Negative Handlungen von Fremdgruppen werden auf deren Charakter geschoben, positive als Ausnahme abgetan.", example: "Foult der Gegner, ist er 'aggressiv' – foult das eigene Team, war es ein Versehen." },
    { name: "Von Restorff Effect (Von-Restorff-Effekt)", cat: "sozial", desc: "Ungewöhnliche oder herausstechende Elemente werden besser erinnert als ähnliche, unauffällige.", example: "In einer Liste grauer Notizen fällt ein roter Zettel sofort auf und wird zuverlässiger erinnert." },
    { name: "Weinstein Effect (Weinstein-Effekt)", cat: "sozial", desc: "Eine öffentliche Enthüllung ermutigt weitere Betroffene, ähnliche Erfahrungen zu berichten, was eine Kettenreaktion auslöst.", example: "Nach den Enthüllungen gegen Harvey Weinstein meldeten sich weltweit weitere Betroffene, was weitere Fälle in verschiedenen Branchen ans Licht brachte." },
    { name: "Mere Exposure Effect (Mere-Exposure-Effekt)", cat: "sozial", desc: "Dinge werden allein durch wiederholte Begegnung positiver bewertet.", example: "Ein Lied, das man zunächst nicht mochte, gefällt nach mehrmaligem Hören zunehmend besser." },
    { name: "Familiarity Bias (Vertrautheitsverzerrung)", cat: "sozial", desc: "Vertraute Dinge werden gegenüber unbekannten bevorzugt, unabhängig von deren objektiver Qualität.", example: "Ein Name, der einem bekannt vorkommt, wird automatisch als glaubwürdiger eingestuft – auch ohne Überprüfung der Quelle." },
    { name: "Curse of Knowledge (Fluch des Wissens)", cat: "sozial", desc: "Experten fällt es schwer, sich vorzustellen, wie es ist, ein Thema nicht zu verstehen, wodurch Erklärungen für Laien zu kompliziert ausfallen.", example: "Ein Softwareentwickler erklärt einem Kunden ein Problem in Fachbegriffen und wundert sich, warum dieser nichts versteht." },
    { name: "Defensive Attribution Hypothesis (Defensive Attributionshypothese)", cat: "sozial", desc: "Betroffenen eines Unglücks wird weniger Verantwortung zugeschrieben, je ähnlicher sie einem selbst erscheinen – um sich emotional zu schützen.", example: "Ein Autofahrer gibt einem in einen Unfall verwickelten Fußgänger mehr Mitschuld, wenn dieser ihm unähnlich erscheint, als wenn er ihm ähnelt." },
    { name: "Extrinsic Incentive Bias (Extrinsische-Anreiz-Verzerrung)", cat: "sozial", desc: "Man geht davon aus, dass andere Menschen stärker von äußeren Anreizen motiviert sind als man selbst.", example: "Eine Führungskraft glaubt, ihre Mitarbeitenden arbeiteten hauptsächlich wegen des Gehalts, während sie ihre eigene Arbeit vor allem intrinsisch motiviert sieht." },
    { name: "Hostile Attribution Bias (Feindselige Attributionsverzerrung)", cat: "sozial", desc: "Mehrdeutiges Verhalten anderer wird tendenziell als absichtlich feindselig interpretiert.", example: "Rempelt jemand versehentlich im Gedränge an, wird das von manchen als bewusste Provokation gedeutet statt als Versehen." },
    { name: "Identifiable Victim Effect (Identifizierbares-Opfer-Effekt)", cat: "sozial", desc: "Einem einzelnen, konkret benannten Betroffenen wird mehr geholfen als einer großen, anonymen Gruppe – selbst wenn diese objektiv mehr Hilfe benötigt.", example: "Eine Spendenkampagne für ein einzelnes, namentlich genanntes Kind sammelt mehr Geld als eine Kampagne für Zehntausende anonyme Betroffene." },
    { name: "Just-World Hypothesis (Glaube an eine gerechte Welt)", cat: "sozial", desc: "Der Glaube, dass die Welt grundsätzlich gerecht ist und Menschen im Wesentlichen das bekommen, was sie verdienen.", example: "Nach einem Unglück wird gefragt, was das Opfer hätte anders machen können – aus dem unbewussten Bedürfnis, an eine gerechte Welt zu glauben." },
    { name: "Moral Credential Effect (Moralische Lizenzierung)", cat: "sozial", desc: "Nach einer moralisch guten Tat erlauben sich Menschen eher ein nachfolgendes fragwürdiges Verhalten, weil sie sich moralisch abgesichert fühlen.", example: "Wer gerade für eine wohltätige Organisation gespendet hat, verhält sich im Anschluss eher rücksichtslos gegenüber Kollegen – im Gefühl, sich das verdient zu haben." },
    { name: "Moral Luck (Moralisches Glück)", cat: "sozial", desc: "Die moralische Bewertung einer Handlung hängt vom tatsächlichen Ergebnis ab, nicht nur von Absicht und Sorgfalt.", example: "Zwei Fahrer fahren gleich unachtsam – nur einer verursacht einen Unfall. Er wird moralisch härter verurteilt, obwohl beide gleich fahrlässig waren." },
    { name: "Out-Group Homogeneity Bias (Fremdgruppen-Homogenitätseffekt)", cat: "sozial", desc: "Mitglieder einer fremden Gruppe werden als untereinander ähnlicher wahrgenommen als Mitglieder der eigenen Gruppe.", example: "'Die sind doch alle gleich' wird oft über eine fremde Gruppe gesagt – über die eigene, vielfältige Gruppe würde man das nie behaupten." },
    { name: "Reactive Devaluation (Reaktive Abwertung)", cat: "sozial", desc: "Ein Vorschlag wird als weniger wertvoll eingeschätzt, allein weil er von einer gegnerischen oder unsympathischen Partei stammt.", example: "In Verhandlungen wird ein Kompromissvorschlag der Gegenseite abgelehnt – obwohl er inhaltlich fast identisch mit der eigenen Forderung ist." },
    { name: "System Justification Bias (System-Rechtfertigungs-Verzerrung)", cat: "sozial", desc: "Bestehende soziale oder organisatorische Systeme werden auch dann als gerecht verteidigt, wenn sie der eigenen Gruppe objektiv schaden.", example: "Mitarbeitende verteidigen eine ungerechte interne Beförderungspraxis, die ihnen selbst schadet, weil sie das bestehende System grundsätzlich für gerecht halten." },
    { name: "Third-Person Effect (Third-Person-Effekt)", cat: "sozial", desc: "Man geht davon aus, dass Massenmedien und Werbung andere Menschen stärker beeinflussen als einen selbst.", example: "Jemand ist überzeugt, Werbung wirke bei ihm kaum, glaubt aber gleichzeitig, dass andere Konsumenten stark von genau dieser Werbung beeinflusst werden." },
    { name: "Trait Ascription Bias (Eigenschaftszuschreibungs-Verzerrung)", cat: "sozial", desc: "Die eigene Persönlichkeit wird als variabel und situationsabhängig wahrgenommen, die anderer Menschen dagegen als festgelegt und vorhersehbar.", example: "Man selbst hat 'einfach einen schlechten Tag' bei einer unhöflichen Reaktion – ein Kollege wird bei gleichem Verhalten grundsätzlich als unhöflicher Mensch wahrgenommen." },
    { name: "Women Are Wonderful Effect (Frauen-sind-wunderbar-Effekt)", cat: "sozial", desc: "Frauen werden in Bewertungen tendenziell positiver assoziiert als Männer, unabhängig von individuellen Eigenschaften.", example: "In Studien werden Begriffe wie 'warmherzig' oder 'hilfsbereit' häufiger automatisch mit Frauen assoziiert als mit Männern – unabhängig vom tatsächlichen Verhalten der bewerteten Person." },
    { name: "Naive Realism (Naiver Realismus)", cat: "sozial", desc: "Der Glaube, die eigene Wahrnehmung der Realität sei objektiv und unverzerrt, während abweichende Meinungen anderer auf deren Voreingenommenheit beruhen.", example: "In einer Diskussion ist jemand überzeugt, einfach nur 'die Fakten' zu sehen – wer anderer Meinung ist, muss demnach uninformiert oder parteiisch sein." },
    { name: "Naive Cynicism (Naiver Zynismus)", cat: "sozial", desc: "Man erwartet von anderen Menschen ein stärker egoistisch motiviertes Verhalten, als man es sich selbst zuschreiben würde.", example: "Ein Verhandlungspartner unterstellt der Gegenseite von vornherein rein eigennützige Motive, während er die eigene Position als fair und ausgewogen betrachtet." },
    { name: "Shared Information Bias (Verzerrung durch geteilte Information)", cat: "sozial", desc: "In Gruppendiskussionen wird bevorzugt über Informationen gesprochen, die bereits allen Mitgliedern bekannt sind – Wissen einzelner Mitglieder bleibt ungenutzt.", example: "In einem Meeting wird ausführlich über allgemein bekannte Fakten diskutiert, während die entscheidende Information einer einzelnen Fachperson nie zur Sprache kommt." },
    { name: "Illusion of Asymmetric Insight (Illusion asymmetrischer Einsicht)", cat: "sozial", desc: "Man glaubt, andere Menschen besser zu kennen und zu verstehen, als sie einen selbst verstehen.", example: "Jemand ist überzeugt, die Motive eines Freundes genau zu durchschauen, geht aber gleichzeitig davon aus, dass die eigenen Beweggründe für andere kaum nachvollziehbar sind." },
    { name: "Illusion of Transparency (Transparenzillusion)", cat: "sozial", desc: "Man überschätzt, wie deutlich andere die eigenen Gedanken und Gefühle erkennen können.", example: "Bei einer nervösen Präsentation glaubt der Redner, seine Aufregung sei für alle im Raum offensichtlich – tatsächlich bemerkt sie kaum jemand." },
    { name: "Gender Bias (Geschlechterverzerrung)", cat: "sozial", desc: "Menschen werden aufgrund ihres Geschlechts unterschiedlich bewertet oder behandelt, unabhängig von ihrer tatsächlichen Leistung oder Eignung.", example: "Bei identischem Lebenslauf wird eine Bewerbung mit männlich klingendem Namen in Studien häufiger zum Gespräch eingeladen als dieselbe Bewerbung mit weiblich klingendem Namen." },
    { name: "Motornormalität (Motornormativity)", cat: "sozial", desc: "Gesellschaftliche Strukturen bevorzugen normative Bewegungsfähigkeiten und machen Menschen mit abweichender Mobilität unsichtbar.", example: "Städte werden primär für schnelle, autonome Mobilität geplant – Menschen mit Mobilitätseinschränkungen, Kinder und ältere Menschen werden dabei systematisch benachteiligt." },
    { name: "Group Attribution Error (Gruppenattributionsfehler)", cat: "sozial", desc: "Das Verhalten einzelner Mitglieder einer Gruppe wird fälschlicherweise als repräsentativ für die gesamte Gruppe gewertet.", example: "Ein schlechtes Erlebnis mit einer Person aus einem bestimmten Land wird als typisch für alle Menschen dieses Landes interpretiert." },
    { name: "In-Group Favoritism (Eigengruppen-Bevorzugung)", cat: "sozial", desc: "Mitglieder der eigenen Gruppe werden systematisch bevorzugt behandelt, auch wenn keine objektiven Gründe dafür vorliegen.", example: "Bei der Vergabe von Aufgaben werden Teammitglieder aus der eigenen Abteilung bevorzugt – obwohl externe Kollegen besser geeignet wären." },
    { name: "Essentialism (Essentialismus)", cat: "sozial", desc: "Gruppen oder Kategorien wird eine unveränderliche, wesenhafte Eigenschaft zugeschrieben, die alle Mitglieder teilen.", example: "Jemand glaubt, Frauen seien 'von Natur aus' fürsorglicher als Männer – ohne kulturelle oder situative Einflüsse zu berücksichtigen." },
    { name: "Reverse Psychology (Umgekehrte Psychologie)", cat: "sozial", desc: "Man fordert bewusst das Gegenteil dessen, was man eigentlich will, um durch Widerstand das gewünschte Verhalten zu provozieren.", example: "Ein Elternteil sagt zum Kind 'Du musst das Gemüse nicht probieren', um es neugierig genug zu machen, es doch zu essen." },
    { name: "Social Comparison Bias (Sozialer-Vergleichs-Verzerrung)", cat: "sozial", desc: "Menschen bevorzugen schwächere Vergleichspartner oder Bewerber, um im Vergleich selbst besser dazustehen.", example: "Eine Führungskraft stellt lieber einen weniger kompetenten Bewerber ein, um die eigene Position nicht zu gefährden." },
    { name: "Implicit Stereotype (Implizites Stereotyp)", cat: "sozial", desc: "Ein Stereotyp, das automatisch und unbewusst aktiviert wird, ohne dass es der Person bewusst zugänglich oder beabsichtigt ist.", example: "Bei der Bewertung eines Lebenslaufs wird bei einem männlich klingenden Namen unwillkürlich eher an 'Softwareentwickler' gedacht als bei einem weiblich klingenden Namen – selbst wenn die Person bewusst von Gleichberechtigung überzeugt ist." },
    { name: "Prejudice (Vorurteil)", cat: "sozial", desc: "Eine emotionale Bewertung oder Haltung gegenüber einer Gruppe, die unabhängig von den individuellen Eigenschaften einzelner Mitglieder besteht.", example: "Jemand empfindet spontan Abneigung gegenüber einer Person, sobald er erfährt, dass sie einer bestimmten Gruppe angehört – unabhängig von deren tatsächlichem Verhalten." },
    { name: "Sleeper Effect (Schläfer-Effekt)", cat: "sozial", desc: "Eine zunächst wenig überzeugende Botschaft wirkt mit zeitlichem Abstand stärker, wenn die unglaubwürdige Quelle vergessen wird, der Inhalt aber erhalten bleibt.", example: "Eine sachlich richtige Aussage einer unbekannten Influencerin wird zunächst abgelehnt – Wochen später überzeugt dieselbe Aussage stärker, weil man sich nicht mehr an die unglaubwürdige Quelle erinnert." },


             // GEDÄCHTNIS //49
    { name: "Backfire Effect (Widerlegungseffekt)", cat: "gedaechtnis", desc: "Gegenbeweise führen dazu, dass man an einer falschen Überzeugung noch stärker festhält.", example: "Eine sachliche Widerlegung einer Verschwörungstheorie lässt den Gläubigen die Theorie noch fester vertreten und die Quelle der Korrektur misstrauen." },
    { name: "Fading Affect Bias (Affektverblassungs-Bias)", cat: "gedaechtnis", desc: "Negative Gefühle verblassen in der Erinnerung schneller als positive.", example: "Ein heftiger Streit wirkt nach Monaten emotional weniger intensiv, während die Freude über dasselbe Ereignis länger bestehen bleibt." },
    { name: "Hindsight Bias (Rückschaufehler)", cat: "gedaechtnis", desc: "Nach einem Ereignis glaubt man, man hätte es vorausgesehen.", example: "Nach einem Börsencrash behaupten viele, sie hätten ihn kommen sehen – obwohl sie vorher keine erhöhte Wahrscheinlichkeit angegeben hatten." },
    { name: "Illusory Truth Effect (Illusory-Truth-Effekt)", cat: "gedaechtnis", desc: "Wiederholte Aussagen werden als wahrer empfunden, unabhängig davon, ob sie stimmen.", example: "Eine falsche Behauptung in sozialen Medien gilt nach mehrfachem Teilen für viele als glaubwürdig – obwohl nie Belege geliefert wurden." },
    { name: "Negativity Bias (Negativitätsverzerrung)", cat: "gedaechtnis", desc: "Negative Erlebnisse prägen sich stärker ein und wirken psychologisch schwerer als positive.", example: "Ein einziges kritisches Feedback überschattet mehrere positive Kommentare und bleibt länger im Gedächtnis." },
    { name: "Primacy Effect (Primäreffekt)", cat: "gedaechtnis", desc: "Zuerst wahrgenommene Informationen werden besser erinnert und gewichten stärker.", example: "Der erste Eindruck in einem Vorstellungsgespräch prägt die Gesamtbewertung stärker als spätere Informationen." },
    { name: "Recency Effect (Rezenzeffekt)", cat: "gedaechtnis", desc: "Zuletzt wahrgenommene Informationen sind präsenter im Gedächtnis als frühere.", example: "In Verhandlungen beeinflussen die zuletzt vorgebrachten Argumente die Entscheidung stärker als frühere." },
    { name: "False Memory (Falsche Erinnerung)", cat: "gedaechtnis", desc: "Erinnerungen an Ereignisse, die nie stattgefunden haben oder anders abgelaufen sind, werden als real erlebt.", example: "Versuchspersonen wurden durch suggestive Hinweise überzeugt, sich lebhaft daran zu erinnern, als Kind in einem Einkaufszentrum verloren gewesen zu sein – obwohl es nie passiert war." },
    { name: "Misinformation Effect (Fehlinformationseffekt)", cat: "gedaechtnis", desc: "Nachträglich erhaltene falsche Informationen verzerren die ursprüngliche Erinnerung.", example: "Zeugen eines Unfalls, die danach eine falsche Beschreibung des Fahrzeugs hören, erinnern sich später an dieses Detail – nicht an das, was sie wirklich gesehen haben." },
    { name: "Source Amnesia (Quellenamnesie)", cat: "gedaechtnis", desc: "Die Herkunft einer Erinnerung wird vergessen, während der Inhalt erhalten bleibt.", example: "Jemand ist überzeugt, eine Idee selbst gehabt zu haben – dabei hat er sie in einem Artikel gelesen, dessen Quelle er vergessen hat." },
    { name: "Cryptomnesia (Kryptomnesia)", cat: "gedaechtnis", desc: "Eine früher wahrgenommene Idee wird unbewusst als eigene neue Idee ausgegeben.", example: "Ein Musiker hält eine Melodie für seine eigene Erfindung – sie ähnelt stark einem Stück, das er vor Jahren gehört, aber bewusst vergessen hat." },
    { name: "Déjà-vu", cat: "gedaechtnis", desc: "Eine neue Situation wird mit dem intensiven Gefühl erlebt, sie bereits einmal erlebt zu haben.", example: "Du betrittst zum ersten Mal ein Café und hast plötzlich das starke Gefühl, genau diesen Moment schon einmal erlebt zu haben." },
    { name: "Jamais-vu", cat: "gedaechtnis", desc: "Eine vertraute Situation oder ein bekanntes Wort wirkt plötzlich völlig fremd und unbekannt.", example: "Beim wiederholten Vorlesen desselben Wortes beginnt es plötzlich, völlig sinnlos und fremd zu wirken." },
    { name: "Mental Set (Einstellungseffekt)", cat: "gedaechtnis", desc: "Einmal gelernte Lösungsstrategien werden stur angewendet, auch wenn eine einfachere Lösung offensichtlich wäre.", example: "Ein Ingenieur greift bei jedem Problem auf dieselbe bewährte Konstruktion zurück – und übersieht dabei eine effizientere, unkonventionelle Lösung." },
    { name: "Rosy Retrospection (Verklärte Rückschau)", cat: "gedaechtnis", desc: "Vergangene Ereignisse werden im Rückblick positiver bewertet, als sie tatsächlich waren.", example: "Nach Jahren erinnert sich ein Student an sein Studium fast nur als schöne Zeit – Stress, Prüfungsangst und finanzielle Sorgen verblassen." },
    { name: "Telescoping Effect (Teleskopierungseffekt)", cat: "gedaechtnis", desc: "Vergangene Ereignisse werden zeitlich näher oder weiter entfernt erinnert, als sie tatsächlich waren.", example: "Jemand gibt an, ein Ereignis 'letzten Monat' erlebt zu haben – tatsächlich war es vor drei Monaten." },
    { name: "Zeigarnik Effect / Incomplete-Task Effect (Zeigarnik-Effekt)", cat: "gedaechtnis", desc: "Unerledigte Aufgaben bleiben besser im Gedächtnis als abgeschlossene.", example: "Eine halb fertig geschriebene E-Mail drängt sich mental stärker auf als eine bereits abgeschickte." },
    { name: "Cue-Dependent Forgetting (Hinweisreizabhängiges Vergessen)", cat: "gedaechtnis", desc: "Gespeicherte Informationen sind nicht abrufbar, weil der passende Kontext oder Auslöser fehlt.", example: "Ein Wort liegt auf der Zunge und fällt einem erst wieder ein, als man an den Ort zurückkehrt, wo man es gelernt hat." },
    { name: "Mood-Congruent Memory Bias (Stimmungskongruente Erinnerung)", cat: "gedaechtnis", desc: "Die aktuelle Stimmung beeinflusst, welche Erinnerungen leichter abgerufen werden.", example: "In trauriger Stimmung fallen einem vor allem andere traurige Erlebnisse ein – positive Erinnerungen treten in den Hintergrund." },
    { name: "Choice-Supportive Bias (Wahl-unterstützende Verzerrung)", cat: "gedaechtnis", desc: "Getroffene Entscheidungen werden im Rückblick positiver bewertet, ihre Vorteile überschätzt und ihre Nachteile unterschätzt.", example: "Wer sich für ein bestimmtes Auto entschieden hat, erinnert sich später vor allem an dessen Stärken – die abgewählten Modelle erscheinen im Rückblick schlechter, als sie tatsächlich waren." },
    { name: "Continued Influence Effect (Fortwirkungseffekt)", cat: "gedaechtnis", desc: "Eine bereits widerlegte Falschinformation beeinflusst weiterhin das Urteilen, selbst nachdem die Korrektur akzeptiert wurde.", example: "Obwohl ein Gerücht offiziell dementiert wurde, bewerten viele die betroffene Person danach unbewusst weiterhin negativer." },
    { name: "Leveling and Sharpening (Nivellierung und Zuspitzung)", cat: "gedaechtnis", desc: "Beim wiederholten Weitererzählen einer Geschichte werden Details abgeschwächt oder übertrieben, wodurch sich die Erinnerung verändert.", example: "Nach mehrfachem Weitererzählen wird aus einem kleinen Vorfall in der Kantine eine dramatische Geschichte – manche Details verschwinden, andere werden übertrieben." },
    { name: "Levels-of-Processing Effect (Verarbeitungstiefen-Effekt)", cat: "gedaechtnis", desc: "Informationen, die tiefer und bedeutungsvoller verarbeitet werden, bleiben besser im Gedächtnis als oberflächlich verarbeitete.", example: "Wer sich beim Lernen eines Wortes bewusst dessen Bedeutung vor Augen führt, erinnert es sich besser, als wenn er nur auf die Schriftart geachtet hätte." },
    { name: "Picture Superiority Effect (Bildüberlegenheitseffekt)", cat: "gedaechtnis", desc: "Bilder werden deutlich besser erinnert als die entsprechenden Wörter oder gesprochene Beschreibungen.", example: "Eine Präsentation mit aussagekräftigen Bildern bleibt Zuschauern länger im Gedächtnis als eine mit reinem Text." },
    { name: "Reminiscence Bump (Erinnerungsbuckel)", cat: "gedaechtnis", desc: "Ältere Menschen erinnern sich überproportional gut an Ereignisse aus ihrer Jugend und dem frühen Erwachsenenalter.", example: "Im Alter erzählt jemand lebhaft von Musik und Ereignissen aus seinen späten Teenagerjahren – während spätere Lebensjahrzehnte blasser in Erinnerung bleiben." },
    { name: "Self-Generation Effect (Selbstgenerierungseffekt)", cat: "gedaechtnis", desc: "Selbst erzeugte Informationen werden besser erinnert als identische, aber nur gelesene oder gehörte Informationen.", example: "Wer eine Rechenaufgabe selbst löst, erinnert sich besser an das Ergebnis, als wenn ihm die Lösung nur vorgelesen wurde." },
    { name: "Self-Reference Effect (Selbstbezugseffekt)", cat: "gedaechtnis", desc: "Informationen mit persönlichem Bezug werden besser erinnert als Informationen ohne Bezug zur eigenen Person.", example: "Eine Liste von Eigenschaftswörtern wird besser erinnert, wenn man zuvor überlegt hat, ob sie auf einen selbst zutreffen." },
    { name: "Spacing Effect (Spacing-Effekt)", cat: "gedaechtnis", desc: "Über die Zeit verteiltes Lernen führt zu einer besseren langfristigen Erinnerung als das Lernen in einer einzigen, geballten Sitzung.", example: "Wer Vokabeln über mehrere Tage verteilt wiederholt, erinnert sie Wochen später deutlich besser, als wer alles am Vorabend der Prüfung einmal durcharbeitet." },
    { name: "Suggestibility (Suggestibilität)", cat: "gedaechtnis", desc: "Durch Fragen, Andeutungen oder Erwartungen anderer beeinflusste Informationen werden als eigene Erinnerung übernommen.", example: "Nach einer suggestiv formulierten Frage ist sich ein Zeuge plötzlich sicher, ein Detail gesehen zu haben, das er zuvor nie erwähnt hatte." },
    { name: "Testing Effect (Testeffekt)", cat: "gedaechtnis", desc: "Aktives Abrufen von Wissen durch Testen führt zu einer besseren langfristigen Erinnerung als reines wiederholtes Lesen.", example: "Wer sich nach dem Lernen selbst abfragt, kann den Stoff Wochen später besser wiedergeben, als wer den Text nur mehrmals durchliest." },
    { name: "Tip-of-the-Tongue Phenomenon (Zungenspitzenphänomen)", cat: "gedaechtnis", desc: "Eine gesuchte Information ist im Gedächtnis vorhanden und fühlt sich abrufbar an, lässt sich im Moment aber nicht vollständig erinnern.", example: "Der Name eines bekannten Schauspielers liegt einem auf der Zunge, fällt einem aber erst Stunden später plötzlich wieder ein." },
    { name: "Humor Effect (Humor-Effekt)", cat: "gedaechtnis", desc: "Humorvoll präsentierte Informationen werden besser erinnert als neutral präsentierte.", example: "Ein Vortrag mit witzigen Beispielen bleibt Zuhörenden länger im Gedächtnis als ein sachlich-trockener Vortrag mit denselben Inhalten." },
    { name: "Positivity Effect (Positivitätseffekt)", cat: "gedaechtnis", desc: "Mit zunehmendem Alter erinnern sich Menschen leichter an positive als an negative Erlebnisse.", example: "Eine ältere Person erzählt bevorzugt von schönen Familienfeiern, während belastende Ereignisse aus derselben Zeit seltener zur Sprache kommen." },
    { name: "Bizarreness Effect (Bizarrheitseffekt)", cat: "gedaechtnis", desc: "Bizarre oder ungewöhnliche Informationen werden besser erinnert als gewöhnliche.", example: "Eine absurde Eselsbrücke – etwa ein tanzendes Einhorn für einen Vokabelbegriff – bleibt länger im Gedächtnis als eine sachliche Assoziation." },
    { name: "Confabulation (Konfabulation)", cat: "gedaechtnis", desc: "Gedächtnislücken werden unbewusst mit erfundenen, aber subjektiv als wahr erlebten Erinnerungen gefüllt.", example: "Ein Patient mit Gedächtnisschäden berichtet überzeugend von Ereignissen, die nie stattgefunden haben – ohne zu lügen oder es zu merken." },
    { name: "Recency Illusion (Neuheitsillusion)", cat: "gedaechtnis", desc: "Man glaubt, ein Wort oder eine Redewendung sei neu oder modern – obwohl es sie schon lange gibt.", example: "Jemand ist überzeugt, das Wort 'literally' werde erst seit kurzem umgangssprachlich verwendet – tatsächlich gibt es diesen Gebrauch seit Jahrhunderten." },
    { name: "Miller's Law (Millersche Zahl)", cat: "gedaechtnis", desc: "Das Arbeitsgedächtnis kann nur etwa 7 (± 2) Informationseinheiten gleichzeitig verarbeiten und behalten.", example: "Telefonnummern werden weltweit meist in Blöcken von 3–4 Ziffern formatiert, weil das Gehirn längere Zahlenfolgen schlechter im Kurzzeitgedächtnis hält." },
    { name: "Generation Effect (Generierungseffekt)", cat: "gedaechtnis", desc: "Aktiv erzeugtes oder ergänztes Lernmaterial wird besser erinnert als passiv gelesenes oder gehörtes – unabhängig davon, wer die Information konkret generiert.", example: "Wer eine Lücke in einem Satz selbst ausfüllt – etwa das Gegenteil von 'heiß' ('kalt') selbst zu finden statt es vorgelesen zu bekommen – erinnert sich später besser daran." },
    { name: "Serial-Position Effect (Serienpositionseffekt)", cat: "gedaechtnis", desc: "Die Erinnerungsleistung an ein Element hängt von seiner Position in einer Reihe ab – der Gesamteffekt aus Primacy und Recency Effect.", example: "Beim Abrufen einer Wortliste werden die ersten und letzten Wörter deutlich besser erinnert als die Wörter aus der Mitte." },
    { name: "Source Confusion (Quellenverwechslung)", cat: "gedaechtnis", desc: "Der Inhalt einer Erinnerung wird korrekt erinnert, aber fälschlicherweise einer falschen Quelle zugeordnet.", example: "Jemand hat eine Behauptung in einem Blog gelesen, ist später aber überzeugt, sie stamme aus einer wissenschaftlichen Studie." },
    { name: "Misattribution of Memory (Fehlzuschreibung von Erinnerungen)", cat: "gedaechtnis", desc: "Der Inhalt einer Erinnerung wird korrekt erinnert, aber fälschlicherweise der falschen Quelle, Zeit oder Person zugeschrieben.", example: "Ein Zeuge ist überzeugt, das Gesicht eines Verdächtigen am Tatort gesehen zu haben – dabei hat er es kurz zuvor in einem Zeitungsartikel gesehen." },
    { name: "Duration Neglect (Dauervernachlässigung)", cat: "gedaechtnis", desc: "Die tatsächliche Dauer eines Erlebnisses hat kaum Einfluss auf die rückblickende Bewertung – entscheidend sind Höhepunkt und Ende.", example: "Eine kurze, aber intensiv unangenehme medizinische Untersuchung wird in der Erinnerung negativer bewertet als eine längere, die am Ende sanft ausklingt." },
    { name: "Modality Effect (Modalitätseffekt)", cat: "gedaechtnis", desc: "Mündlich dargebotene Informationen werden am Ende einer Liste besser erinnert als schriftlich dargebotene.", example: "Bei einer mündlich genannten Telefonnummer erinnert man sich an die letzten Ziffern besser, als wenn dieselbe Nummer nur schriftlich gezeigt wird." },
    { name: "Memory Inhibition (Gedächtnishemmung)", cat: "gedaechtnis", desc: "Das gezielte Abrufen bestimmter Erinnerungen kann das Erinnern verwandter, aber nicht abgerufener Informationen erschweren.", example: "Wer sich intensiv an bestimmte Details eines Urlaubs erinnert, vergisst dadurch leichter andere, ähnliche Details desselben Urlaubs." },
    { name: "Part-Set Cuing Effect (Teilmengen-Hinweis-Effekt)", cat: "gedaechtnis", desc: "Das Vorgeben eines Teils der zu erinnernden Elemente kann das Erinnern der übrigen Elemente erschweren statt erleichtern.", example: "Werden beim Rekonstruieren einer Einkaufsliste bereits einige Artikel genannt, erinnert man sich an die restlichen oft schlechter, als wenn man ganz ohne Hinweise startet." },
    { name: "Suffix Effect (Suffix-Effekt)", cat: "gedaechtnis", desc: "Ein zusätzliches, bedeutungsloses Element am Ende einer Liste verschlechtert die Erinnerung an die letzten eigentlichen Listenelemente.", example: "Wird nach einer Zahlenreihe noch ein belangloses Wort wie 'Ende' gesagt, erinnert man sich schlechter an die letzten Zahlen, als wenn die Liste ohne diesen Zusatz endet." },
    { name: "Absent-Mindedness (Geistesabwesenheit)", cat: "gedaechtnis", desc: "Mangelnde Aufmerksamkeit beim Enkodieren einer Information führt dazu, dass sie später nicht abrufbar ist.", example: "Jemand legt die Autoschlüssel ab, während er gedanklich beim Telefonat ist, und kann sich später nicht erinnern, wo er sie hingelegt hat." },
    { name: "Next-in-Line Effect (Nächster-Effekt)", cat: "gedaechtnis", desc: "Wer sich auf den eigenen bevorstehenden Redebeitrag konzentriert, erinnert sich schlechter an das, was der unmittelbar vorherige Sprecher gesagt hat.", example: "In einer Reihe von Kurzpräsentationen kann sich die nächste Rednerin kaum an den Inhalt der direkt vorherigen Präsentation erinnern, weil sie gedanklich schon bei der eigenen ist." },
    { name: "List-Length Effect (Listenlängeneffekt)", cat: "gedaechtnis", desc: "Je länger eine Liste von Elementen ist, desto geringer ist der Anteil der Elemente, die korrekt erinnert werden.", example: "Beim Auswendiglernen einer Einkaufsliste erinnert man sich bei 5 Artikeln fast an alle, bei 20 Artikeln aber nur an einen deutlich kleineren Anteil." },


             // METHODIK / STATISTIK //30
    { name: "Algorithmic Bias (Algorithmische Verzerrung)", cat: "methodik", desc: "Algorithmen produzieren systematisch fehlerhafte Ergebnisse, weil ihre Trainingsdaten bereits verzerrt sind.", example: "Eine KI zur Kreditvergabe lehnt bestimmte Bevölkerungsgruppen häufiger ab, weil historische Daten deren Benachteiligung widerspiegeln." },
    { name: "Attrition Bias (Ausfallverzerrung)", cat: "methodik", desc: "Wenn Studienteilnehmer vorzeitig ausscheiden und das nicht zufällig passiert, verzerrt das die Ergebnisse.", example: "In einer Diätstudie brechen vor allem erfolglose Teilnehmer ab – die Ergebnisse wirken besser als sie sind." },
    { name: "Confounding Bias (Störvariablen-Verzerrung)", cat: "methodik", desc: "Ein übersehener dritter Faktor täuscht einen kausalen Zusammenhang zwischen zwei Variablen vor.", example: "Eisverkauf und Ertrinkungsunfälle korrelieren – die Störvariable ist das warme Wetter." },
    { name: "Publication Bias (Publikationsverzerrung)", cat: "methodik", desc: "Studien mit positiven Ergebnissen werden häufiger veröffentlicht, was ein verzerrtes Bild der Forschungslage erzeugt.", example: "Ein Medikament wirkt in der Literatur überzeugend, weil die vielen erfolglosen Studien dazu nie publiziert wurden." },
    { name: "Selection Bias (Auswahlverzerrung)", cat: "methodik", desc: "Die Stichprobe ist nicht repräsentativ, weil die Auswahl der Teilnehmer systematisch verzerrt ist.", example: "Eine Online-Umfrage über Internetnutzung schließt automatisch alle aus, die kein Internet haben." },
    { name: "Survivorship Bias / Survivor Bias (Überlebensverzerrung)", cat: "methodik", desc: "Man zieht Schlüsse nur aus den 'Überlebenden' eines Prozesses und ignoriert alle Gescheiterten.", example: "Erfolgreiche Unternehmer gelten als Beweis, dass Risikobereitschaft sich lohnt – die vielen Gescheiterten mit derselben Strategie bleiben unsichtbar." },
    { name: "Regression to the Mean (Regression zur Mitte)", cat: "methodik", desc: "Extreme Messwerte nähern sich bei Wiederholung dem Durchschnitt an – nicht wegen einer Intervention, sondern aus statistischen Gründen.", example: "Ein Sportler nach einer Ausnahmeleistung erbringt danach wieder durchschnittlichere Ergebnisse, unabhängig vom Training." },
    { name: "Law of Large Numbers (Gesetz der großen Zahlen)", cat: "methodik", desc: "Mit wachsender Stichprobengröße nähert sich der Mittelwert dem wahren Erwartungswert an – wird aber oft fälschlicherweise auf kleine Stichproben angewendet.", example: "Jemand erwartet nach fünf Mal 'Kopf', dass nun 'Zahl' kommen muss – das Gesetz gilt nur langfristig." },
    { name: "Gambler's Fallacy (Spielerfehlschluss)", cat: "methodik", desc: "Der Irrglaube, dass vergangene Zufallsereignisse die Wahrscheinlichkeit zukünftiger beeinflussen.", example: "Nach zehnmal Rot beim Roulette wettet jemand auf Schwarz, weil es 'dran' sei – dabei bleibt die Wahrscheinlichkeit gleich." },
    { name: "Multiple Comparisons Problem (Multiples Testen)", cat: "methodik", desc: "Je mehr Hypothesen man gleichzeitig testet, desto wahrscheinlicher ist ein zufällig signifikantes Ergebnis.", example: "Wer genug Nahrungsmittel auf Krebskorrelation testet, findet irgendwann eines – rein zufällig." },
    { name: "P-Hacking (Datenmassage)", cat: "methodik", desc: "Forscher passen Analysen oder Daten so lange an, bis ein statistisch signifikantes Ergebnis entsteht.", example: "Eine Studie testet viele Subgruppen und berichtet nur die eine, in der das Medikament wirkt." },
    { name: "Hawthorne Effect (Hawthorne-Effekt)", cat: "methodik", desc: "Menschen verändern ihr Verhalten allein dadurch, dass sie wissen, dass sie beobachtet werden.", example: "Mitarbeiter arbeiten produktiver, sobald sie wissen, dass ihre Leistung im Rahmen einer Studie gemessen wird." },
    { name: "Placebo Effect (Placebo-Effekt)", cat: "methodik", desc: "Allein die Erwartung einer wirksamen Behandlung kann zu messbarer Verbesserung führen.", example: "Patienten mit Zuckerpillen berichten von echter Schmerzlinderung, weil sie eine Wirkung erwarten." },
    { name: "Nocebo Effect (Nocebo-Effekt)", cat: "methodik", desc: "Negative Erwartungen an eine Behandlung können reale, negative Symptome auslösen.", example: "Patienten, die über mögliche Nebenwirkungen informiert werden, erleiden diese häufiger – auch bei Placebos." },
    { name: "Observer Bias (Beobachterverzerrung)", cat: "methodik", desc: "Die Erwartungen oder Vorannahmen eines Beobachters beeinflussen unbewusst seine Wahrnehmung und Auswertung.", example: "Ein Arzt, der an ein neues Medikament glaubt, bewertet die Fortschritte seiner Patienten unbewusst positiver." },
    { name: "Recall Bias (Erinnerungsverzerrung)", cat: "methodik", desc: "Teilnehmer erinnern sich an vergangene Ereignisse ungenau oder selektiv, was die Daten verzerrt.", example: "Erkrankte Menschen erinnern sich im Nachhinein detaillierter an frühere Risikofaktoren als Gesunde." },
    { name: "Reporting Bias (Berichterstattungsverzerrung)", cat: "methodik", desc: "Nur ein Teil der erhobenen Ergebnisse wird berichtet – meist der günstige.", example: "Ein Pharmaunternehmen veröffentlicht nur die Studienarme, in denen das Mittel besser abschnitt." },
    { name: "Response Bias (Antwortverzerrung)", cat: "methodik", desc: "Befragte antworten nicht wahrheitsgemäß, sondern so, wie sie glauben, dass es erwartet wird.", example: "In einer Umfrage zum Alkoholkonsum nennen viele niedrigere Mengen als tatsächlich getrunken." },
    { name: "Texas Sharpshooter Fallacy (Texas-Scharfschützen-Fehlschluss)", cat: "methodik", desc: "Man erkennt ein Muster in Zufallsdaten erst nachträglich und behandelt es so, als wäre es vorhergesagt worden.", example: "Ein Forscher analysiert 50 Variablen, findet zufällig eine Korrelation und baut daraus eine Theorie – ohne vorherige Hypothese." },
    { name: "Sampling Bias (Wahlverzerrung)", cat: "methodik", desc: "Die Stichprobe repräsentiert die Zielpopulation nicht, weil die Auswahl systematisch bestimmte Gruppen bevorzugt.", example: "Eine Straßenumfrage tagsüber erfasst kaum Berufstätige und gibt ein schiefes Bild der Meinung wieder." },
    { name: "Ecological Fallacy (Ökologische Fehlschluss)", cat: "methodik", desc: "Schlüsse über Individuen werden fälschlicherweise aus aggregierten Daten gezogen.", example: "In einer Stadt mit hoher Kriminalitätsrate wird angenommen, dass jeder Einwohner kriminell ist – obwohl die meisten gesetzestreu sind." },
    { name: "Goodhart's Law (Goodhart'sches Gesetz)", cat: "methodik", desc: "Wenn ein Maßstab zum Ziel wird, verliert er seine Aussagekraft.", example: "Ein Unternehmen misst die Produktivität anhand der Anzahl abgeschlossener Aufgaben – Mitarbeiter erledigen viele kleine Aufgaben, aber die Qualität leidet." },
    { name: "Insensitivity to Sample Size (Unempfindlichkeit gegenüber Stichprobengröße)", cat: "methodik", desc: "Die Zuverlässigkeit eines Ergebnisses wird unabhängig von der Stichprobengröße gleich eingeschätzt, obwohl kleine Stichproben viel stärker schwanken.", example: "Eine kleine Klinik mit wenigen Geburten pro Tag hat häufiger Tage mit auffällig hohem Jungenanteil als eine große Klinik – wird aber in der Wahrnehmung genauso bewertet." },
    { name: "Neglect of Probability (Wahrscheinlichkeitsvernachlässigung)", cat: "methodik", desc: "Bei Entscheidungen unter Unsicherheit werden tatsächliche Wahrscheinlichkeiten weitgehend ignoriert, statt sie angemessen zu gewichten.", example: "Viele fürchten sich stärker vor Flugzeugabstürzen als vor Autounfällen, obwohl Autofahren statistisch weit gefährlicher ist – die Wahrscheinlichkeiten werden dabei ausgeblendet." },
    { name: "Omitted Variable Bias (Bias durch ausgelassene Variable)", cat: "methodik", desc: "Eine relevante Variable wird in einer statistischen Analyse nicht berücksichtigt, wodurch die geschätzten Zusammenhänge zwischen den einbezogenen Variablen verzerrt werden.", example: "Eine Studie zu Bildung und Einkommen lässt die Variable 'familiärer Hintergrund' außen vor – dadurch wirkt der Zusammenhang zwischen Bildung und Einkommen stärker, als er tatsächlich ist." },
    { name: "Illusory Correlation (Illusorische Korrelation)", cat: "methodik", desc: "Zwischen zwei Ereignissen oder Variablen wird ein Zusammenhang wahrgenommen, der statistisch gar nicht besteht.", example: "Jemand ist überzeugt, dass Vollmond zu mehr Notaufnahmebesuchen führt – Studien zeigen dafür keinen statistischen Zusammenhang." },
    { name: "Surrogation (Ersatzzielverzerrung)", cat: "methodik", desc: "Eine Kennzahl wird über die Zeit mit dem eigentlichen strategischen Ziel verwechselt, das sie ursprünglich nur repräsentieren sollte.", example: "Ein Vertriebsteam verfolgt nur noch die Anzahl abgeschlossener Verkäufe als Ziel – die ursprüngliche Absicht, langfristige Kundenbeziehungen aufzubauen, gerät dabei aus dem Blick." },
    { name: "Bias-Variance Tradeoff (Verzerrungs-Varianz-Kompromiss)", cat: "methodik", desc: "Ein Modell mit geringer Verzerrung neigt zu hoher Varianz bei neuen Daten und umgekehrt – Genauigkeit und Stabilität stehen im Konflikt.", example: "Ein sehr einfaches Vorhersagemodell liefert stabile, aber ungenaue Ergebnisse – ein sehr komplexes Modell passt sich den Trainingsdaten gut an, schwankt aber stark bei neuen Daten." },
    { name: "Observer Bias (Beobachterverzerrung)", cat: "methodik", desc: "Jede Form systematischer Verzerrung durch Beobachter, die unbewusst Daten anders wahrnehmen oder interpretieren als sie tatsächlich sind.", example: "Eine Ärztin misst einen Hautbefund bei zwei Patientinnen – weil sie weiß, dass Patientin A hohes Risiko hat, interpretiert sie Randbereiche unbewusst anders als bei Patientin B." },
    { name: "Conjunction Fallacy (Konjunktionsfehlschluss)", cat: "methodik", desc: "Die Wahrscheinlichkeit einer Kombination zweier Ereignisse wird höher eingeschätzt als die Wahrscheinlichkeit eines der Einzelereignisse.", example: "Beim Linda-Problem von Tversky und Kahneman halten die meisten Menschen es für wahrscheinlicher, dass Linda 'Bankangestellte und Feministin' ist, als nur 'Bankangestellte' – obwohl das statistisch unmöglich ist." },

            // WAHRNEHMUNG //35
    { name: "Attentional Bias (Aufmerksamkeitsverzerrung)", cat: "wahrnehmung", desc: "Die Aufmerksamkeit richtet sich bevorzugt auf bestimmte Reize, wodurch andere Informationen vernachlässigt werden.", example: "Ein Arzt bemerkt vor allem Symptome, die zu einer kürzlich gesehenen Diagnose passen, und übersieht Hinweise auf eine andere Krankheit." },
    { name: "Change Blindness (Veränderungsblindheit)", cat: "wahrnehmung", desc: "Offensichtliche Veränderungen in einer visuellen Szene werden nicht wahrgenommen, wenn die Aufmerksamkeit kurz unterbrochen wird.", example: "In einem Experiment wird während eines kurzen Schnitts die Person im Bild ausgetauscht – die meisten Beobachter bemerken es nicht." },
    { name: "Inattentional Blindness (Unaufmerksamkeitsblindheit)", cat: "wahrnehmung", desc: "Unerwartete Objekte oder Ereignisse werden nicht wahrgenommen, wenn die Aufmerksamkeit auf etwas anderes gerichtet ist.", example: "Versuchspersonen, die Pässe beim Basketball zählen, übersehen einen Mann im Gorillakostüm, der durchs Bild läuft." },
    { name: "Hemispatial Neglect (Halbseitiger Neglect)", cat: "wahrnehmung", desc: "Nach einer Hirnverletzung wird eine Seite des Wahrnehmungsfeldes systematisch ignoriert.", example: "Ein Patient nach einem Schlaganfall isst nur die rechte Hälfte des Tellers und rasiert nur die rechte Gesichtshälfte." },
    { name: "Perceptual Set (Wahrnehmungseinstellung)", cat: "wahrnehmung", desc: "Erwartungen und Erfahrungen beeinflussen, wie eingehende Reize wahrgenommen und interpretiert werden.", example: "Wer gerade an Autos denkt, erkennt in einer mehrdeutigen Zeichnung eher ein Auto als ein anderes Objekt." },
    { name: "Size-Weight Illusion (Größen-Gewichts-Illusion)", cat: "wahrnehmung", desc: "Kleinere Objekte werden als schwerer wahrgenommen als gleich schwere, aber größere Objekte.", example: "Eine kleine Metallkugel fühlt sich schwerer an als ein gleich schwerer, aber größerer Schaumstoffblock." },
    { name: "Stroop Effect (Stroop-Effekt)", cat: "wahrnehmung", desc: "Die Reaktionszeit verzögert sich, wenn die Bedeutung eines Wortes und seine Farbe nicht übereinstimmen.", example: "Das Wort 'ROT' in blauer Farbe zu benennen dauert länger als das Wort 'BLAU' in blauer Farbe." },
    { name: "Visual Illusions (Visuelle Illusionen)", cat: "wahrnehmung", desc: "Visuelle Reize werden so fehlinterpretiert, dass die Wahrnehmung nicht der Realität entspricht.", example: "Bei der Müller-Lyer-Illusion wirken zwei gleich lange Linien unterschiedlich lang, je nachdem, wie die Pfeilspitzen ausgerichtet sind." },
    { name: "Auditory Illusions (Akustische Illusionen)", cat: "wahrnehmung", desc: "Akustische Reize werden so fehlinterpretiert, dass das Gehörte nicht dem tatsächlichen Klang entspricht.", example: "Der Shepard-Ton erweckt den Eindruck eines endlos ansteigenden Tons, obwohl die Tonhöhe in Wirklichkeit konstant bleibt." },
    { name: "Vividness Bias (Lebendigkeitseffekt)", cat: "wahrnehmung", desc: "Lebendige oder emotionale Informationen werden stärker gewichtet als nüchterne statistische Fakten.", example: "Nach einem dramatischen Flugzeugunglück im Fernsehen überschätzen viele die Absturzwahrscheinlichkeit – obwohl Fliegen statistisch sehr sicher ist." },
    { name: "Contrast Effect (Kontrasteffekt)", cat: "wahrnehmung", desc: "Die Wahrnehmung eines Reizes wird durch einen vorherigen, kontrastierenden Reiz verzerrt.", example: "Eine Gehaltserhöhung von 200 € wirkt enttäuschend, wenn man vorher mit 500 € gerechnet hat – obwohl 200 € objektiv positiv sind." },
    { name: "Adaptation Level Effect (Adaptionsniveau-Effekt)", cat: "wahrnehmung", desc: "Die Wahrnehmung von Reizen passt sich an den gewohnten Durchschnitt an, sodass neue Reize relativ dazu bewertet werden.", example: "Jemand, der aus einer lauten Stadt in eine ruhige Gegend zieht, empfindet normale Alltagsgeräusche zunächst als unerträglich laut." },
    { name: "Pareidolia", cat: "wahrnehmung", desc: "Das Gehirn erkennt bedeutungsvolle Muster – meist Gesichter – in zufälligen oder unstrukturierten Reizen.", example: "In einem Stück Toast wird das Gesicht einer berühmten Person gesehen, obwohl es sich um zufällige Bräunungsmuster handelt." },
    { name: "Body Ownership Illusion (Körperbesitz-Illusion)", cat: "wahrnehmung", desc: "Das Gehirn kann künstliche oder fremde Körperteile als zum eigenen Körper gehörig wahrnehmen.", example: "Beim Gummihand-Experiment fühlt sich eine Versuchsperson nach kurzer Zeit so, als gehöre eine Gummihand zu ihrem eigenen Körper." },
    { name: "McGurk Effect (McGurk-Effekt)", cat: "wahrnehmung", desc: "Visuelle Mundbewegungen beeinflussen die akustische Wahrnehmung von Lauten – Hören und Sehen werden unbewusst kombiniert.", example: "Sieht man jemanden 'ga' sagen, während man 'ba' hört, nimmt man oft 'da' wahr – obwohl keiner dieser Laute tatsächlich produziert wurde." },
    { name: "Weapon Focus Effect (Waffenfokus-Effekt)", cat: "wahrnehmung", desc: "In bedrohlichen Situationen richtet sich die Aufmerksamkeit auf die Waffe, was die Erinnerung an andere Details verschlechtert.", example: "Zeugen eines Überfalls erinnern sich detailliert an die Waffe des Täters, können aber Gesicht, Kleidung oder Fluchtrichtung kaum beschreiben." },
    { name: "Rubber Hand Illusion (Gummihand-Illusion)", cat: "wahrnehmung", desc: "Durch synchrone taktile und visuelle Reize wird eine künstliche Hand als Teil des eigenen Körpers wahrgenommen.", example: "Wenn eine Gummihand und die echte Hand gleichzeitig berührt werden, fühlen viele Versuchspersonen die Berührung in der Gummihand." },
    { name: "Temporal Discounting in Perception (Zeitliche Wahrnehmungsverzerrung)", cat: "wahrnehmung", desc: "Zeitlich nahe Ereignisse werden intensiver und größer wahrgenommen als gleich bedeutsame, aber weiter entfernte Ereignisse.", example: "Eine Prüfung in drei Tagen erzeugt mehr Stress als dieselbe Prüfung in drei Monaten – obwohl Schwierigkeit und Bedeutung identisch sind." },
    { name: "Phonemic Restoration Effect (Phonemwiederherstellungs-Effekt)", cat: "wahrnehmung", desc: "Fehlende oder verdeckte Laute in gesprochener Sprache werden vom Gehirn automatisch ergänzt.", example: "Wird in einem Satz ein Laut durch ein Hustengeräusch ersetzt, hören die meisten Menschen trotzdem das vollständige Wort – ohne die Lücke zu bemerken." },
    { name: "Tactile Illusion (Taktile Illusion)", cat: "wahrnehmung", desc: "Das Tastsystem erzeugt Wahrnehmungen, die nicht der physikalischen Realität entsprechen.", example: "Beim Aristoteles-Täuschungs-Experiment fühlt sich eine einzelne Kugel, die mit gekreuzten Fingern berührt wird, wie zwei separate Kugeln an." },
    { name: "Motion-Induced Blindness (Bewegungsinduzierte Blindheit)", cat: "wahrnehmung", desc: "Statische Objekte verschwinden vorübergehend aus der Wahrnehmung, wenn sie von bewegten Mustern umgeben sind.", example: "Fixiert man einen bewegten Hintergrund, verschwinden statische gelbe Punkte im Sichtfeld zeitweise vollständig – obwohl sie physisch vorhanden sind." },
    { name: "Size Constancy (Größenkonstanz)", cat: "wahrnehmung", desc: "Objekte werden als gleich groß wahrgenommen, obwohl ihr Abbild auf der Netzhaut bei zunehmendem Abstand kleiner wird.", example: "Ein Mensch in 50 Metern Entfernung wirkt nicht wie ein Zwerg, obwohl sein Netzhautbild winzig ist – das Gehirn korrigiert automatisch." },
    { name: "Illusion of Competence (Illusion der Kompetenz)", cat: "wahrnehmung", desc: "Menschen überschätzen ihre Fähigkeiten in einem bestimmten Bereich, besonders wenn sie wenig Erfahrung haben.", example: "Ein Anfänger im Schach glaubt, er könne gegen erfahrene Spieler gewinnen, obwohl seine tatsächlichen Fähigkeiten begrenzt sind." },
    { name: "Anthropomorphism (Anthropomorphismus)", cat: "wahrnehmung", desc: "Tieren, Objekten und abstrakten Konzepten werden menschliche Eigenschaften, Gefühle und Absichten zugeschrieben.", example: "Ein Autobesitzer spricht mit seinem Auto und ist überzeugt, es habe an manchen Tagen eine 'schlechte Laune'." },
    { name: "Functional Fixedness (Funktionale Fixierung)", cat: "wahrnehmung", desc: "Ein Objekt wird nur in seiner gewohnten Funktion wahrgenommen, alternative Verwendungsmöglichkeiten werden dabei übersehen.", example: "Beim Duncker-Kerzenproblem sehen die meisten Menschen eine Reißzweckenschachtel nur als Behälter – nicht als möglichen Kerzenhalter an der Wand." },
    { name: "Weber-Fechner Law (Weber-Fechner-Gesetz)", cat: "wahrnehmung", desc: "Kleine Unterschiede in großen Reizmengen werden schwerer wahrgenommen als gleich große Unterschiede in kleinen Reizmengen.", example: "Der Unterschied zwischen 1 und 2 Kerzen im dunklen Raum ist deutlich sichtbar – der gleiche Helligkeitsunterschied fällt bei 100 zu 101 Kerzen kaum noch auf." },
    { name: "Well-Travelled Road Effect (Vielbefahrene-Straße-Effekt)", cat: "wahrnehmung", desc: "Die Dauer einer vertrauten Strecke wird unterschätzt, die einer neuen, unbekannten Strecke dagegen überschätzt.", example: "Der tägliche Arbeitsweg fühlt sich kürzer an als eine neue, objektiv gleich lange Route, die man zum ersten Mal fährt." },
    { name: "Salience Bias (Salienzverzerrung)", cat: "wahrnehmung", desc: "Auffällige, hervorstechende Reize ziehen überproportional viel Aufmerksamkeit auf sich und beeinflussen dadurch das Urteil stärker als unauffällige, aber relevantere Informationen.", example: "Bei einer Präsentation bleibt vor allem die eine grelle rote Folie im Gedächtnis – die inhaltlich wichtigeren, schlichter gestalteten Folien geraten in Vergessenheit." },
    { name: "Frequency Illusion (Frequenzillusion)", cat: "wahrnehmung", desc: "Nachdem man etwas zum ersten Mal bemerkt hat, nimmt man es plötzlich überall wahr – obwohl es vorher genauso häufig vorkam.", example: "Wer sich ein bestimmtes Auto kauft, sieht dieses Modell plötzlich überall auf der Straße – obwohl es vorher genauso häufig fuhr." },
    { name: "Selective Perception (Selektive Wahrnehmung)", cat: "wahrnehmung", desc: "Menschen nehmen bevorzugt Informationen wahr, die ihren Erwartungen und Überzeugungen entsprechen, und blenden Widersprüchliches aus.", example: "Ein überzeugter Fußballfan sieht Fouls des Gegners sofort – Fouls des eigenen Teams fallen ihm kaum auf." },
    { name: "Subjective Validation (Subjektive Validierung)", cat: "wahrnehmung", desc: "Eine Aussage wird als wahr empfunden, weil sie persönlich bedeutsam erscheint – unabhängig davon, ob sie objektiv zutrifft.", example: "Jemand ist überzeugt, dass sein Horoskop ihn perfekt beschreibt – obwohl dieselbe Beschreibung auf Millionen andere zutrifft." },
    { name: "Cheerleader Effect (Cheerleader-Effekt)", cat: "wahrnehmung", desc: "Personen werden als attraktiver wahrgenommen, wenn sie in einer Gruppe sind, als wenn sie alleine betrachtet werden.", example: "Ein Gruppenfoto wirkt attraktiver als die Einzelfotos derselben Personen – das Gehirn mittelt die Gesichter und gleicht Unregelmäßigkeiten aus." },
    { name: "Well-Travelled Road Effect (Vielbefahrene-Straße-Effekt)", cat: "wahrnehmung", desc: "Die Dauer einer vertrauten Strecke wird unterschätzt, die einer neuen, unbekannten Strecke dagegen überschätzt.", example: "Der tägliche Arbeitsweg fühlt sich kürzer an als eine neue, objektiv gleich lange Route, die man zum ersten Mal fährt." },
    { name: "Processing Difficulty Effect (Verarbeitungsschwierigkeits-Effekt)", cat: "wahrnehmung", desc: "Informationen, die schwerer zu verarbeiten sind, werden manchmal gründlicher verarbeitet und dadurch besser behalten.", example: "Ein Text in einer schwer leserlichen Schriftart wird manchmal besser erinnert als derselbe Text in einer gut leserlichen Schrift, weil das Gehirn ihn aufmerksamer verarbeitet." },


            // LOGIK //38
    { name: "Affirming the Consequent (Bestätigung des Folgesatzes)", cat: "logik", desc: "Aus 'Wenn A, dann B' wird fälschlicherweise 'B, also A' gefolgert.", example: "Die Straße ist nass, also hat es geregnet – dabei könnte sie auch gewaschen worden sein." },
    { name: "Denying the Antecedent (Verneinung des Vordersatzes)", cat: "logik", desc: "Aus 'Wenn A, dann B' wird fälschlicherweise 'Nicht A, also nicht B' gefolgert.", example: "Es regnet nicht, also ist die Straße nicht nass – obwohl sie nass sein könnte, weil jemand sie gewaschen hat." },
    { name: "Circular Reasoning / Begging the Question (Zirkelschluss)", cat: "logik", desc: "Die Schlussfolgerung wiederholt lediglich die Prämisse, ohne unabhängige Belege zu liefern.", example: "Das Produkt ist gut, weil viele es kaufen – und viele kaufen es, weil es gut ist." },
    { name: "False Dilemma / False Dichotomy (Falsches Dilemma)", cat: "logik", desc: "Eine Situation wird als Entweder-oder-Wahl dargestellt, obwohl weitere Optionen existieren.", example: "Entweder du bist für uns oder gegen uns – eine dritte Position wird nicht zugelassen." },
    { name: "Hasty Generalization (Vorschnelle Verallgemeinerung)", cat: "logik", desc: "Aus wenigen oder unrepräsentativen Beispielen wird eine weitreichende Schlussfolgerung gezogen.", example: "Zwei Personen aus diesem Land waren unhöflich – also sind alle dort unhöflich." },
    { name: "Post Hoc Ergo Propter Hoc (Nach diesem, also wegen diesem)", cat: "logik", desc: "Weil Ereignis B auf Ereignis A folgt, wird angenommen, dass A die Ursache von B ist.", example: "Ich habe einen Glücksbringer getragen und dann gewonnen – also bringt er Glück." },
    { name: "Red Herring (Ablenkungsmanöver)", cat: "logik", desc: "Ein irrelevantes Thema wird in eine Diskussion eingeführt, um von der eigentlichen Argumentation abzulenken.", example: "In einer Debatte über Umweltschutz wechselt jemand das Thema zu Wirtschaftswachstum, ohne auf das Argument einzugehen." },
    { name: "Slippery Slope (Dammbruch-Argument)", cat: "logik", desc: "Eine kleine erste Handlung wird als unweigerlicher Auslöser einer Kette negativer Konsequenzen dargestellt.", example: "Wenn wir Schuluniformen einführen, wird das irgendwann zu totaler Gleichmacherei und dem Ende der Individualität führen." },
    { name: "Straw Man (Strohmann-Argument)", cat: "logik", desc: "Das Argument des Gegenübers wird verzerrt oder vereinfacht, um es leichter angreifbar zu machen.", example: "Jemand fordert weniger Autoverkehr in der Stadt – der Gegner antwortet: 'Du willst also alle Autos verbieten?'" },
    { name: "Tu Quoque (Auch-du-Argument)", cat: "logik", desc: "Ein Vorwurf wird abgewehrt, indem darauf hingewiesen wird, dass der Ankläger dasselbe tut.", example: "Ein Politiker wird für Korruption kritisiert und antwortet: 'Die Opposition hat das doch auch gemacht.'" },
    { name: "False Cause (Falsche Ursache)", cat: "logik", desc: "Zwei zeitlich zusammenfallende Ereignisse werden als Ursache und Wirkung interpretiert, ohne dass ein kausaler Zusammenhang besteht.", example: "Seit mehr Menschen Bio kaufen, steigt die Zahl psychischer Erkrankungen – also macht Bio-Ernährung krank." },
    { name: "Ad Hominem (Angriff auf die Person)", cat: "logik", desc: "Ein Argument wird nicht inhaltlich widerlegt, sondern die Person angegriffen, die es vorträgt.", example: "Statt auf das Argument einzugehen, sagt jemand: 'Du kannst über Wirtschaft nichts wissen, du hast ja nie studiert.'" },
    { name: "Ad Populum (Appell an die Masse)", cat: "logik", desc: "Eine Aussage wird als wahr angesehen, weil viele Menschen sie glauben.", example: "Millionen Menschen glauben an Astrologie, also muss etwas daran dran sein." },
    { name: "Appeal to Nature (Appell an die Natur)", cat: "logik", desc: "Etwas wird als gut oder richtig bewertet, weil es natürlich ist – und umgekehrt als schlecht, weil es unnatürlich ist.", example: "'Dieses Produkt ist völlig natürlich, also ist es gesund' – obwohl viele natürliche Substanzen giftig sind." },
    { name: "Appeal to Authority (Appell an die Autorität)", cat: "logik", desc: "Eine Aussage wird als wahr akzeptiert, weil eine Autoritätsperson sie behauptet – unabhängig von Belegen.", example: "'Ein bekannter Schauspieler empfiehlt dieses Nahrungsergänzungsmittel, also muss es wirken.'" },
    { name: "Appeal to Emotion (Appell an die Emotion)", cat: "logik", desc: "Emotionale Reaktionen werden genutzt, um eine Schlussfolgerung zu stützen, statt sachlicher Argumente.", example: "Ein Politiker zeigt Bilder von leidenden Kindern, um eine Gesetzesänderung zu rechtfertigen – ohne inhaltliche Begründung." },
    { name: "False Equivalence (Falsche Gleichsetzung)", cat: "logik", desc: "Zwei Dinge werden als gleichwertig dargestellt, obwohl sie sich wesentlich unterscheiden.", example: "'Wissenschaftler sind sich über den Klimawandel uneinig' – dabei sind 97 % der Klimaforscher einer Meinung, und eine kleine Minderheit wird gleichwertig dargestellt." },
    { name: "Nirvana Fallacy (Nirvana-Fehlschluss)", cat: "logik", desc: "Eine reale Lösung wird abgelehnt, weil sie nicht perfekt ist – obwohl keine perfekte Alternative existiert.", example: "'Dieses Gesetz löst das Problem nicht vollständig, also sollten wir es gar nicht einführen' – obwohl es deutliche Verbesserungen bringen würde." },
    { name: "Burden of Proof Fallacy (Beweislastfehlschluss)", cat: "logik", desc: "Die Beweislast wird fälschlicherweise umgekehrt – derjenige, der eine Behauptung aufstellt, verlangt vom Gegenüber, sie zu widerlegen.", example: "'Beweise, dass Geister nicht existieren' – obwohl derjenige, der ihre Existenz behauptet, die Beweispflicht trägt." },
    { name: "Equivocation (Äquivokation)", cat: "logik", desc: "Ein Begriff wird innerhalb eines Arguments in unterschiedlichen Bedeutungen verwendet, was zu einer falschen Schlussfolgerung führt.", example: "'Licht ist das Gegenteil von Dunkel. Federn sind leicht. Also sind Federn das Gegenteil von Dunkel.' – das Wort 'leicht' wird in zwei verschiedenen Bedeutungen genutzt." },
    { name: "Composition Fallacy (Kompositionsfehlschluss)", cat: "logik", desc: "Eigenschaften eines Teils werden fälschlicherweise auf das Ganze übertragen.", example: "'Jedes Teil dieses Autos ist leicht, also muss das ganze Auto leicht sein' – obwohl die Summe der Teile schwer sein kann." },
    { name: "Division Fallacy (Teilungsfehlschluss)", cat: "logik", desc: "Eigenschaften des Ganzen werden fälschlicherweise auf einzelne Teile übertragen.", example: "'Dieses Orchester ist weltklasse, also muss jeder einzelne Musiker darin weltklasse sein.'" },
    { name: "Genetic Fallacy (Genetischer Fehlschluss)", cat: "logik", desc: "Ein Argument wird allein aufgrund seiner Herkunft oder Quelle bewertet, nicht aufgrund seines Inhalts.", example: "'Diese Idee stammt aus dem 19. Jahrhundert, also kann sie nicht mehr relevant sein' – ohne den Inhalt zu prüfen." },
    { name: "Middle Ground Fallacy (Goldene-Mitte-Fehlschluss)", cat: "logik", desc: "Ein Kompromiss zwischen zwei Positionen wird als richtig angenommen, obwohl eine der Positionen klar falsch sein kann.", example: "'Manche sagen, die Erde ist 4,5 Milliarden Jahre alt, andere sagen 6.000 Jahre – die Wahrheit liegt wohl irgendwo in der Mitte.'" },
    { name: "Wishful Thinking (Wunschdenken)", cat: "logik", desc: "Eine Überzeugung wird als wahr angenommen, weil man sich wünscht, dass sie wahr ist – nicht aufgrund von Belegen.", example: "'Mein Startup wird sicher erfolgreich, weil ich so hart daran gearbeitet habe' – ohne die tatsächlichen Marktbedingungen zu berücksichtigen." },
    { name: "Modus Tollens Misuse (Modus-Tollens-Missbrauch)", cat: "logik", desc: "Die gültige Schlussregel 'Wenn A, dann B; nicht B, also nicht A' wird falsch angewendet oder auf ungültige Fälle übertragen.", example: "'Alle Terroristen essen Brot. Er isst Brot, also ist er ein Terrorist' – die Schlussregel wird umgekehrt und falsch angewendet." },
    { name: "Kettle Logic (Kessellogik)", cat: "logik", desc: "Mehrere widersprüchliche Argumente werden gleichzeitig vorgebracht, um eine Aussage zu verteidigen.", example: "'Ich habe dir den Topf unbeschädigt zurückgegeben, er hatte schon vorher ein Loch, und ich habe dir gar keinen Topf geliehen.'" },
    { name: "No True Scotsman (Kein-echter-Schotte-Fehlschluss)", cat: "logik", desc: "Eine widerlegte Aussage über eine Gruppe wird gerettet, indem der Gegenfall als 'kein echtes Mitglied' der Gruppe definiert wird.", example: "'Kein echter Schotte würde so etwas tun' – als Reaktion auf den Hinweis, dass ein Schotte genau das getan hat." },
    { name: "Begging the Question Variant (Petitio Principii)", cat: "logik", desc: "Die Schlussfolgerung eines Arguments wird bereits als Prämisse vorausgesetzt, ohne sie zu belegen.", example: "'Die Bibel ist wahr, weil sie Gottes Wort ist, und Gott lügt nicht, weil es in der Bibel steht.'" },
    { name: "Fallacy of Composition vs Division (Ganzes-Teil-Fehlschluss)", cat: "logik", desc: "Was für das Individuum gilt, wird fälschlicherweise auf die Gruppe übertragen – oder umgekehrt.", example: "'Wenn alle Zuschauer aufstehen, sehen alle besser – also sollte jeder aufstehen' – was für den Einzelnen gilt, gilt nicht für alle gleichzeitig." },
    { name: "Moving the Goalposts (Torpfosten verschieben)", cat: "logik", desc: "Werden Belege für eine Behauptung geliefert, werden die Anforderungen für einen Beweis nachträglich erhöht.", example: "'Zeig mir einen einzigen Fall!' – nach dem Vorlegen des Falls: 'Das zählt nicht, zeig mir hundert Fälle!'" },
    { name: "Argument from Ignorance (Argumentum ad Ignorantiam)", cat: "logik", desc: "Weil etwas nicht widerlegt wurde, wird es als wahr angenommen – oder umgekehrt.", example: "'Es wurde nie bewiesen, dass Außerirdische nicht existieren, also gibt es sie.'" },
    { name: "Loaded Question (Suggestivfrage)", cat: "logik", desc: "Eine Frage enthält eine versteckte Prämisse, die der Befragte durch jede Antwort implizit bestätigt.", example: "'Haben Sie aufgehört, Ihren Partner zu schlagen?' – jede Antwort setzt voraus, dass es vorher der Fall war." },
    { name: "Appeal to Novelty (Neuheitsappell)", cat: "logik", desc: "Etwas wird als besser oder richtiger bewertet, allein weil es neu oder modern ist.", example: "'Diese Methode ist brandneu, also muss sie besser funktionieren als die alte' – ohne dass die neue Methode tatsächlich belegt bessere Ergebnisse liefert." },
    { name: "Masked-Man Fallacy (Maskierter-Mann-Fehlschluss)", cat: "logik", desc: "Aus der unterschiedlichen Beschreibung desselben Objekts wird fälschlicherweise auf zwei verschiedene Objekte geschlossen.", example: "'Lois Lane weiß, dass Superman fliegen kann, aber nicht, dass Clark Kent fliegen kann – also sind Superman und Clark Kent verschiedene Personen.' Obwohl sie dieselbe Person sind." },
    { name: "Argument from Fallacy (Fehlschluss aus dem Fehlschluss)", cat: "logik", desc: "Weil ein Argument einen logischen Fehler enthält, wird angenommen, dass die Schlussfolgerung falsch sein muss.", example: "'Dein Argument für den Klimawandel ist ein Strohmann-Argument – also gibt es keinen Klimawandel.' Ein schlechtes Argument macht die Schlussfolgerung nicht automatisch falsch." },
    { name: "Appeal to Probability (Appell an die Wahrscheinlichkeit)", cat: "logik", desc: "Weil etwas möglich oder wahrscheinlich ist, wird angenommen, dass es zwingend eintreten wird.", example: "'Irgendwann wird es einen großen Cyberangriff geben – also sollten wir jetzt schon so handeln, als wäre er bereits passiert.'" },
    { name: "Tolerance Paradox (Toleranz-Paradoxon)", cat: "logik", desc: "Eine unbegrenzt tolerante Gesellschaft wird schließlich von Intoleranten übernommen – unbegrenzte Toleranz schließt also ihre eigene Abschaffung ein.", example: "'Wenn wir alle Meinungen tolerieren, müssen wir auch intolerante Meinungen tolerieren – was letztlich die Toleranz selbst zerstört.'" },


            // TECHNIK //17
    { name: "Automation Bias (Automatisierungsverzerrung)", cat: "technik", desc: "Menschen vertrauen automatisierten Systemen übermäßig und übernehmen deren Vorschläge unkritisch.", example: "Viele Menschen vertrauen KI-generierten Inhalten, ohne sie kritisch zu prüfen, obwohl bekannt ist, dass KI auch halluzinieren kann." },
    { name: "Filter Bubble (Filterblase)", cat: "technik", desc: "Algorithmen zeigen bevorzugt Inhalte, die den eigenen Vorlieben entsprechen, was die Wahrnehmung der Realität verengt.", example: "Wer politisch links orientiert ist, sieht in sozialen Medien fast nur linke Inhalte – und glaubt, die Mehrheit denke genauso." },
    { name: "Technochauvinism (Techno-Chauvinismus)", cat: "technik", desc: "Die Überzeugung, dass technologische Lösungen menschlichen Fähigkeiten grundsätzlich überlegen sind.", example: "Ein Unternehmen ersetzt erfahrene Kundenberater durch einen Chatbot – weil Technologie per se als besser gilt, nicht weil es die Daten belegen." },
    { name: "Data Bias (Datenverzerrung)", cat: "technik", desc: "Verzerrte oder unrepräsentative Datensätze führen zu fehlerhaften Analysen und Entscheidungen.", example: "Ein Gesichtserkennungssystem wurde hauptsächlich mit hellen Gesichtern trainiert und erkennt dunkle Hauttöne deutlich schlechter." },
    { name: "Automation Paradox (Automatisierungsparadoxon)", cat: "technik", desc: "Mehr Automatisierung kann neue, vorher nicht existierende Fehlerquellen schaffen und die menschliche Kompetenz im Umgang mit Ausnahmesituationen verringern.", example: "Piloten, die fast nur noch auf den Autopiloten vertrauen, verlieren Routine im manuellen Fliegen – und reagieren in Notfällen langsamer." },
    { name: "Overfitting (Überanpassung)", cat: "technik", desc: "Ein Modell passt sich zu stark an die Trainingsdaten an und versagt bei neuen, unbekannten Daten.", example: "Ein KI-Modell erkennt Katzenfotos aus dem Trainingsdatensatz perfekt, scheitert aber an leicht anderen Bildern aus dem echten Leben." },
    { name: "Underfitting (Unteranpassung)", cat: "technik", desc: "Ein Modell ist zu simpel, um die Muster in den Daten zu erfassen, und liefert auch bei bekannten Daten schlechte Ergebnisse.", example: "Ein lineares Modell soll den Verlauf einer Kurve vorhersagen – es trifft weder die Trainingsdaten noch neue Daten gut." },
    { name: "Simpson's Paradox (Simpsons Paradoxon)", cat: "technik", desc: "Ein Trend, der in einzelnen Gruppen sichtbar ist, kann verschwinden oder sich umkehren, wenn die Gruppen zusammengefasst werden.", example: "Eine Behandlung wirkt in jeder Altersgruppe besser als die Alternative – in der Gesamtstatistik schneidet sie aber schlechter ab, weil die Gruppen unterschiedlich groß sind." },
    { name: "Echo Chamber Effect (Echokammer-Effekt)", cat: "technik", desc: "Digitale Plattformen verstärken bestehende Überzeugungen, indem gleichgesinnte Meinungen immer wieder zurückgespiegelt werden.", example: "In einer geschlossenen Facebook-Gruppe werden nur Beiträge geteilt, die die eigene politische Meinung bestätigen – abweichende Stimmen werden blockiert oder ignoriert." },
    { name: "Black Box Problem (Schwarzes-Kasten-Problem)", cat: "technik", desc: "Komplexe KI-Modelle treffen Entscheidungen, deren Logik selbst für Experten nicht nachvollziehbar ist.", example: "Ein KI-System lehnt einen Kreditantrag ab, aber weder der Antragsteller noch die Bank kann erklären, welche Faktoren dazu geführt haben." },
    { name: "Concept Drift (Konzeptverschiebung)", cat: "technik", desc: "Die statistischen Eigenschaften der Zielvariable ändern sich über die Zeit, wodurch ein trainiertes Modell zunehmend ungenau wird.", example: "Ein Spam-Filter, der vor drei Jahren trainiert wurde, erkennt moderne Spam-Nachrichten kaum noch, weil sich Sprache und Muster der Angreifer verändert haben." },
    { name: "Feedback Loop Bias (Rückkopplungsschleifen-Verzerrung)", cat: "technik", desc: "Algorithmen verstärken bestehende Verzerrungen, weil ihre eigenen Entscheidungen die Daten erzeugen, auf denen sie weiter trainiert werden.", example: "Ein Empfehlungsalgorithmus zeigt einer Person immer extremere Inhalte, weil sie auf ähnliche Inhalte geklickt hat – die Klicks bestätigen den Algorithmus und verstärken den Effekt." },
    { name: "Automation Complacency (Automatisierungsblindheit)", cat: "technik", desc: "Durch übermäßiges Vertrauen in automatisierte Systeme sinkt die Wachsamkeit des Menschen, was Fehler unbemerkt lässt.", example: "Ein Operateur eines Kernkraftwerks bemerkt einen Systemfehler nicht, weil er darauf vertraut, dass die Automatisierung ihn warnen würde." },
    { name: "Digital Redlining (Digitale Ausgrenzung)", cat: "technik", desc: "Algorithmen und digitale Systeme benachteiligen systematisch bestimmte Bevölkerungsgruppen, oft ohne explizite Diskriminierungsabsicht.", example: "Ein Algorithmus zur Kreditvergabe benachteiligt Bewohner bestimmter Postleitzahlen, die historisch einkommensschwach sind – obwohl die individuelle Bonität gut ist." },
    { name: "Technology Adoption Bias (Technologieadoptions-Verzerrung)", cat: "technik", desc: "Neue Technologien werden von bestimmten Bevölkerungsgruppen schneller übernommen, was zu verzerrten Daten und Designentscheidungen führt.", example: "Eine App wird hauptsächlich von jungen, technikaffinen Nutzern getestet – die Bedürfnisse älterer oder weniger technikaffiner Nutzer fließen kaum ins Design ein." },
    { name: "Not Invented Here Syndrome (Nicht-hier-erfunden-Syndrom)", cat: "technik", desc: "Lösungen, Ideen oder Technologien aus externen Quellen werden abgewertet, allein weil sie nicht intern entstanden sind.", example: "Ein Entwicklungsteam lehnt eine bewährte externe Softwarebibliothek ab und programmiert lieber eine eigene, schlechtere Lösung von Grund auf." },
    { name: "Digital Amnesia / Google-Effekt (Digitale Amnesie)", cat: "technik", desc: "Informationen, von denen man weiß, dass sie jederzeit online nachschlagbar sind, werden schlechter im eigenen Gedächtnis behalten.", example: "Wer sich sicher ist, eine Information jederzeit googeln zu können, merkt sie sich deutlich schlechter, als wenn er wüsste, dass sie später nicht mehr verfügbar wäre." },

             // ANTI-BIASES //25
    { name: "Debiasing (Entzerrung)", cat: "anti-bias", desc: "Gezielte Strategien und Techniken, die kognitive Verzerrungen im Denken und Verhalten reduzieren oder ausschalten sollen.", example: "Vor einer Entscheidung werden bewusst Gegenargumente gesucht, um den Confirmation Bias abzuschwächen." },
    { name: "Blind Spot Bias (Blinder-Fleck-Verzerrung)", cat: "anti-bias", desc: "Die Tendenz, bei sich selbst weniger Verzerrungen wahrzunehmen als bei anderen – nach dem Motto: 'Ich bin objektiv, andere sind voreingenommen.'", example: "Jemand kritisiert einen Kollegen für voreingenommene Urteile – ohne zu merken, dass er selbst denselben Bias zeigt." },
    { name: "Counterfactual Thinking (Kontrafaktisches Denken)", cat: "anti-bias", desc: "Das bewusste Durchdenken alternativer Szenarien hilft, Ursachen und Auswirkungen von Verzerrungen besser zu verstehen.", example: "Nach einem Misserfolg fragt man sich: 'Was wäre passiert, wenn ich früher um Feedback gebeten hätte?' – um künftige Entscheidungen zu verbessern." },
    { name: "Perspective-Taking (Perspektivwechsel)", cat: "anti-bias", desc: "Die bewusste Einnahme einer fremden Perspektive fördert Empathie und hilft, Vorurteile abzubauen.", example: "Eine Führungskraft versetzt sich in die Lage einer Mitarbeiterin aus einer marginalisierten Gruppe, bevor sie eine Personalentscheidung trifft." },
    { name: "Stereotype Threat (Stereotypenbedrohung)", cat: "anti-bias", desc: "Die Angst, ein negatives Stereotyp über die eigene Gruppe zu bestätigen, kann die tatsächliche Leistung messbar verschlechtern.", example: "Frauen, die vor einem Mathetest an Geschlechterunterschiede erinnert werden, schneiden im Schnitt schlechter ab als ohne diesen Hinweis." },
    { name: "Implicit Association Test / IAT (Impliziter Assoziationstest)", cat: "anti-bias", desc: "Ein psychologisches Messverfahren, das unbewusste Vorurteile und automatische Assoziationen sichtbar macht.", example: "Der IAT misst, wie schnell jemand bestimmte Begriffe mit positiven oder negativen Wörtern verknüpft – und deckt so unbewusste Vorurteile auf." },
    { name: "Diversity Training (Diversitätstraining)", cat: "anti-bias", desc: "Strukturierte Programme, die das Bewusstsein für Vielfalt stärken und Vorurteile in Organisationen reduzieren sollen.", example: "Ein Unternehmen schult Personalverantwortliche darin, Lebensläufe anonymisiert zu bewerten, um Affinity Bias bei der Auswahl zu verringern." },
    { name: "Cognitive Reframing (Kognitive Umstrukturierung)", cat: "anti-bias", desc: "Eine Situation oder Information wird bewusst aus einer anderen Perspektive betrachtet, um verzerrte Denkmuster aufzubrechen.", example: "Statt 'Ich bin bei der Präsentation gescheitert' denkt jemand: 'Ich habe gelernt, wie ich mich beim nächsten Mal besser vorbereite.'" },
    { name: "Counter-Stereotyping (Gegen-Stereotypisierung)", cat: "anti-bias", desc: "Stereotype werden aktiv hinterfragt, indem gezielt Gegenbeispiele hervorgehoben werden.", example: "In Schulbüchern werden bewusst Frauen in technischen Berufen und Männer in Pflegeberufen gezeigt, um Berufsrollenstereotype aufzuweichen." },
    { name: "Intergroup Contact Theory (Intergruppenkonktakt-Theorie)", cat: "anti-bias", desc: "Direkter Kontakt zwischen Mitgliedern verschiedener Gruppen kann Vorurteile abbauen, wenn Bedingungen wie Gleichstellung und gemeinsame Ziele erfüllt sind.", example: "Schüler aus verschiedenen ethnischen Gruppen arbeiten in einem gemeinsamen Schulprojekt zusammen – und entwickeln dabei weniger Vorurteile gegeneinander." },
    { name: "Allyship (Verbündetsein)", cat: "anti-bias", desc: "Aktives Eintreten für die Rechte und das Wohl marginalisierter Gruppen, um Diskriminierung entgegenzuwirken.", example: "Eine nicht betroffene Person spricht in einem Meeting aktiv aus, wenn eine Kollegin unterbrochen oder übergangen wird." },
    { name: "Empathy Training (Empathietraining)", cat: "anti-bias", desc: "Gezielte Übungen und Programme stärken die Fähigkeit zur Empathie und helfen, Vorurteile gegenüber anderen Gruppen zu reduzieren.", example: "In einem Workshop schlüpfen Teilnehmer in Rollenspiele, um die Erfahrungen von Diskriminierung aus der Perspektive Betroffener zu erleben." },
    { name: "Bias Awareness Training (Bias-Bewusstseinstraining)", cat: "anti-bias", desc: "Programme, die gezielt das Bewusstsein für kognitive Verzerrungen schärfen und deren Auswirkungen auf Entscheidungen verdeutlichen.", example: "Ärzte werden in Workshops darauf hingewiesen, wie Confirmation Bias ihre Diagnosen beeinflussen kann – und lernen Gegenstrategien." },
    { name: "Socratic Questioning (Sokratisches Fragen)", cat: "anti-bias", desc: "Durch gezieltes Hinterfragen von Annahmen und Überzeugungen werden Denkverzerrungen aufgedeckt und kritisches Denken gefördert.", example: "Ein Coach fragt einen Manager: 'Woher wissen Sie, dass Ihre Einschätzung korrekt ist?' – und deckt so unbewusste Vorannahmen auf." },
    { name: "Pre-Mortem Analysis (Vorausschauende Fehleranalyse)", cat: "anti-bias", desc: "Bevor eine Entscheidung umgesetzt wird, wird gedanklich durchgespielt, warum sie scheitern könnte – um blinde Flecken zu erkennen.", example: "Ein Team stellt sich vor der Produkteinführung vor, das Projekt sei gescheitert, und analysiert rückwirkend mögliche Ursachen – um sie vorher zu beheben." },
    { name: "Devil's Advocate (Advocatus Diaboli)", cat: "anti-bias", desc: "Eine Person übernimmt bewusst die Gegenposition, um Schwachstellen in Argumenten und Gruppenentscheidungen aufzudecken.", example: "In einem Meeting wird jemand beauftragt, alle Gegenargumente zu einem Vorschlag zu sammeln – auch wenn er persönlich dafür ist." },
    { name: "Structured Decision Making (Strukturierte Entscheidungsfindung)", cat: "anti-bias", desc: "Entscheidungen werden anhand vorher festgelegter Kriterien und Prozesse getroffen, um spontane Verzerrungen zu minimieren.", example: "Bei Bewerbungsgesprächen werden alle Kandidaten anhand derselben Fragen und Bewertungsrubrik beurteilt – statt nach Bauchgefühl." },
    { name: "Red Team Thinking (Roter-Team-Ansatz)", cat: "anti-bias", desc: "Eine unabhängige Gruppe wird beauftragt, eine Entscheidung oder Strategie aktiv zu hinterfragen und Schwachstellen zu finden.", example: "Ein Unternehmen lässt eine separate Gruppe die eigene Sicherheitsstrategie angreifen, um Lücken zu finden, die das eigene Team übersehen hat." },
    { name: "Mindfulness (Achtsamkeit)", cat: "anti-bias", desc: "Bewusstes Wahrnehmen eigener Gedanken und Reaktionen im Moment hilft, automatische Verzerrungen zu erkennen, bevor sie Entscheidungen beeinflussen.", example: "Vor einer wichtigen Entscheidung hält jemand inne und fragt sich: 'Reagiere ich gerade auf Fakten oder auf Emotionen?'" },
    { name: "Anonymization (Anonymisierung)", cat: "anti-bias", desc: "Das Entfernen identifizierender Merkmale aus Entscheidungsprozessen reduziert unbewusste Vorurteile gegenüber Personen.", example: "Lebensläufe werden ohne Namen, Foto und Adresse bewertet, damit Personalentscheider nicht durch Herkunft oder Geschlecht beeinflusst werden." },
    { name: "Feedback Culture (Feedbackkultur)", cat: "anti-bias", desc: "Eine offene Kultur, in der regelmäßiges, ehrliches Feedback gegeben und empfangen wird, hilft, blinde Flecken im eigenen Denken zu erkennen.", example: "Ein Team führt regelmäßige Retrospektiven durch, in denen auch unbequeme Wahrheiten über Fehlentscheidungen offen besprochen werden." },
    { name: "Slowing Down Decisions (Entschleunigung von Entscheidungen)", cat: "anti-bias", desc: "Bewusstes Verlangsamen von Entscheidungsprozessen reduziert impulsive, verzerrungsanfällige Schnellurteile.", example: "Eine Unternehmensregel besagt, dass keine wichtige Personalentscheidung am selben Tag getroffen werden darf, an dem das Gespräch stattfand." },
    { name: "Statistical Literacy Training (Statistisches Grundbildungstraining)", cat: "anti-bias", desc: "Das Erlernen statistischer Grundkonzepte hilft, häufige kognitive Verzerrungen bei der Interpretation von Daten zu vermeiden.", example: "Nach einem Workshop über Basisraten und Stichprobengrößen bewerten Ärzte Testergebnisse deutlich nüchterner und genauer." },
    { name: "Psychological Safety (Psychologische Sicherheit)", cat: "anti-bias", desc: "Ein Teamklima, in dem sich Mitglieder trauen, Fehler, Bedenken oder abweichende Meinungen offen zu äußern, ohne negative Konsequenzen zu befürchten.", example: "In einem Team mit hoher psychologischer Sicherheit meldet ein Mitarbeiter frühzeitig einen eigenen Fehler – und verhindert so einen größeren Schaden für das Projekt." },
    { name: "Occam's Razor (Ockhams Rasiermesser)", cat: "anti-bias", desc: "Unter mehreren Erklärungen für einen Sachverhalt sollte die mit den wenigsten Annahmen, also die einfachste Antwort, bevorzugt werden.", example: "Springt das Auto nicht an, ist eine leere Batterie die naheliegendere Erklärung als eine Sabotage – auch wenn beides theoretisch möglich wäre." },
    
            // HEURISTIKEN //15
    { name: "Representativeness Heuristic (Repräsentativitätsheuristik)", cat: "heuristik", desc: "Wahrscheinlichkeiten werden danach eingeschätzt, wie sehr etwas einem typischen Prototyp ähnelt.", example: "Jemand schließt, dass eine ruhige, brillentragende Person eher Bibliothekar als LKW-Fahrer ist – obwohl es statistisch viel mehr LKW-Fahrer gibt." },
    { name: "Anchoring Heuristic (Ankerheuristik)", cat: "heuristik", desc: "Der erste genannte Wert dient als Anker und beeinflusst alle folgenden Schätzungen unverhältnismäßig stark.", example: "Ein Verkäufer nennt zuerst einen überhöhten Preis – der tatsächliche Verkaufspreis wirkt danach wie ein Schnäppchen, auch wenn er noch immer hoch ist." },
    { name: "Affect Heuristic (Affektheuristik)", cat: "heuristik", desc: "Entscheidungen werden stärker von aktuellen Gefühlen und Stimmungen geleitet als von rationaler Abwägung.", example: "In guter Stimmung bewertet man Risiken geringer und trifft optimistischere Entscheidungen – etwa beim Kauf einer Aktie." },
    { name: "Availability Heuristic (Verfügbarkeitsheuristik)", cat: "heuristik", desc: "Die Häufigkeit oder Wahrscheinlichkeit eines Ereignisses wird danach eingeschätzt, wie leicht man sich Beispiele dafür vorstellen kann.", example: "Nach mehreren Flugzeugabsturzberichten meiden Menschen das Fliegen – obwohl Autofahren statistisch gefährlicher ist." },
    { name: "Simulation Heuristic (Simulationsheuristik)", cat: "heuristik", desc: "Die Wahrscheinlichkeit eines Ereignisses wird danach bewertet, wie leicht man sich seinen Ablauf oder alternative Ausgänge gedanklich vorstellen kann.", example: "Wer sich lebhaft vorstellen kann, knapp einen Unfall vermieden zu haben, empfindet das Ereignis als gefährlicher als jemand, dem diese Vorstellung schwerfällt." },
    { name: "Recognition Heuristic (Wiedererkennungsheuristik)", cat: "heuristik", desc: "Wenn eine von zwei Optionen bekannt ist und die andere nicht, wird die bekannte als die bessere eingestuft.", example: "Gefragt, welche Stadt größer ist – Frankfurt oder Paderborn – wählen die meisten Frankfurt, allein weil sie den Namen kennen." },
    { name: "Take-the-Best Heuristic (Nimm-das-Beste-Heuristik)", cat: "heuristik", desc: "Bei Entscheidungen wird nur das wichtigste Kriterium herangezogen und alle weiteren ignoriert.", example: "Bei der Jobwahl entscheidet jemand ausschließlich anhand des Gehalts – Arbeitsklima, Aufgaben und Entwicklungsmöglichkeiten werden nicht berücksichtigt." },
    { name: "Fluency Heuristic (Flüssigkeitsheuristik)", cat: "heuristik", desc: "Informationen, die sich leichter verarbeiten lassen, werden als wahrer, häufiger oder wertvoller eingestuft.", example: "Ein Produktname, der sich leicht ausspricht, wird als vertrauenswürdiger wahrgenommen als ein komplizierter Name – unabhängig von der tatsächlichen Qualität." },
    { name: "Scarcity Heuristic (Knappheitsheuristik)", cat: "heuristik", desc: "Dinge, die selten oder schwer verfügbar sind, werden automatisch als wertvoller eingestuft.", example: "'Nur noch 2 Stück verfügbar' lässt ein Produkt begehrenswerter erscheinen – auch wenn es vorher kaum Interesse geweckt hat." },
    { name: "Social Proof Heuristic (Soziale-Beweis-Heuristik)", cat: "heuristik", desc: "Das Verhalten anderer wird als Orientierung genutzt, um die richtige Entscheidung in unklaren Situationen zu treffen.", example: "Ein Restaurant mit vielen Gästen wird als besser eingestuft als ein leeres – allein weil viele andere dort essen." },
    { name: "Default Heuristic (Standard-Heuristik)", cat: "heuristik", desc: "Voreingestellte Optionen werden beibehalten, weil aktives Entscheiden als aufwändig wahrgenommen wird.", example: "Die meisten Nutzer behalten die voreingestellten Datenschutzeinstellungen einer App bei, anstatt sie aktiv anzupassen." },
    { name: "Effort Heuristic (Aufwandsheuristik)", cat: "heuristik", desc: "Der wahrgenommene Aufwand hinter einem Produkt oder einer Leistung wird als Indikator für dessen Qualität genutzt.", example: "Ein handgefertigtes Möbelstück wird als hochwertiger eingestuft als ein maschinell produziertes – obwohl die objektive Qualität gleich sein kann." },
    { name: "Peak-End Rule (Spitzenwert-Ende-Regel)", cat: "heuristik", desc: "Erlebnisse werden nicht nach ihrem Durchschnitt bewertet, sondern fast ausschließlich nach dem intensivsten Moment und dem Ende.", example: "Ein Urlaub mit einem grandiosen letzten Tag wird besser erinnert als ein gleichmäßig angenehmer Urlaub ohne herausragendes Ende." },
    { name: "Rhyme-as-Reason Effect (Reim-als-Vernunft-Effekt)", cat: "heuristik", desc: "Aussagen, die sich reimen, werden als wahrer oder überzeugender eingeschätzt als inhaltlich identische, nicht gereimte Aussagen.", example: "Werbeslogans, die sich reimen, wie 'Ehrmann, keiner macht mich mehr an', wirken einprägsamer und überzeugender als sachliche Aussagen – unabhängig vom Wahrheitsgehalt." },
    { name: "Complexity Bias (Komplexitätsverzerrung)", cat: "heuristik", desc: "Komplexe Erklärungen oder Lösungen werden als glaubwürdiger oder richtiger wahrgenommen als einfache.", example: "Ein kompliziert klingender medizinischer Fachbegriff wird eher als valide Diagnose akzeptiert als eine einfache Erklärung – auch wenn beide gleichwertig sind. Z.B. Jemand erklärt einen Leistungsabfall mit einem komplexen Zusammenspiel aus Hormonen, Persönlichkeit und sozialen Faktoren (Schlafmangel)." },
]

// Such- und Filterfunktionen sowie die Logik zum Rendern der Bias-Karten
document.addEventListener('DOMContentLoaded', () => {
    const grid = document.getElementById('bias-grid');
    const searchInput = document.getElementById('searchInput');
    const filterContainer = document.getElementById('filter-container');
    const sortContainer = document.getElementById('sort-container');

    function renderCards(data) {
        grid.innerHTML = '';
        data.forEach(bias => {
            const card = document.createElement('div');
            card.className = 'bias-card';
            card.dataset.category = bias.cat;
            card.dataset.name = bias.name;
            card.dataset.example = bias.example;
            
           
            card.innerHTML = `
                <span class="category-tag">${bias.cat}</span>
                <h2>${bias.name}</h2>
                <p class="description">${bias.desc}</p>
                <p class="example"><em>${bias.example}</em></p>
            `;

            // oben: Um Beispiele/ example anzuzeigen, muss im biases Array ein entsprechendes Feld mit Text gefüllt werden. Sonst wird es leer angezeigt.
            
            card.onclick = () => {
                const wasActive = card.classList.contains('active');
                document.querySelectorAll('.bias-card').forEach(c => c.classList.remove('active'));
                if (!wasActive) card.classList.add('active');
            };
            
            grid.appendChild(card);
        });
    }

    // Ermittelt, WO ein Suchbegriff trifft: 'name' (hohe Relevanz) oder 'text'
    // (nur in Beschreibung/Beispiel gefunden, niedrigere Relevanz). null = kein Treffer.
    function getMatchType(bias, search) {
        if (!search) return 'match';
        if (bias.name.toLowerCase().includes(search)) return 'name';
        if (bias.desc.toLowerCase().includes(search) || bias.example.toLowerCase().includes(search)) return 'text';
        return null;
    }

    function update() {
        const search = searchInput.value.toLowerCase().trim();
        const activeFilter = filterContainer.querySelector('.filter-btn.active').dataset.filter;
        const activeSort = sortContainer.querySelector('.sort-btn.active').dataset.sort;

        let filtered = biases
            .map(b => ({ bias: b, matchType: getMatchType(b, search) }))
            .filter(entry => {
                const matchesFilter = activeFilter === 'all' || entry.bias.cat === activeFilter;
                return matchesFilter && entry.matchType !== null;
            });

        if (activeSort === 'asc') {
            filtered.sort((a, b) => a.bias.name.localeCompare(b.bias.name));
        } else if (activeSort === 'desc') {
            filtered.sort((a, b) => b.bias.name.localeCompare(a.bias.name));
        } else if (search) {
            // Standard-Sortierung + aktive Suche: Treffer im Namen zuerst,
            // danach Treffer, die nur in Beschreibung/Beispiel gefunden wurden.
            filtered.sort((a, b) => (a.matchType === b.matchType) ? 0 : (a.matchType === 'name' ? -1 : 1));
        }

        const results = filtered.map(entry => entry.bias);
        renderCards(results);

        if (results.length === 0) {
            grid.innerHTML = '<p class="no-results">Keine Treffer gefunden. Versuche einen anderen Suchbegriff oder Filter.</p>';
        }
    }

    // Debounce: erst 120ms nach der letzten Eingabe wird tatsächlich gefiltert/gerendert,
    // damit nicht bei jedem Tastendruck die volle Filter- und Render-Pipeline läuft.
    let searchDebounce;
    searchInput.oninput = () => {
        clearTimeout(searchDebounce);
        searchDebounce = setTimeout(update, 120);
    };

    filterContainer.onclick = (e) => {
        if (!e.target.classList.contains('filter-btn')) return;
        filterContainer.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
        e.target.classList.add('active');
        update();
    };

    sortContainer.onclick = (e) => {
        if (!e.target.classList.contains('sort-btn')) return;
        sortContainer.querySelectorAll('.sort-btn').forEach(b => b.classList.remove('active'));
        e.target.classList.add('active');
        update();
    };

    renderCards(biases);
});